pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Aggressive 2-step lookahead: if the next item fits exactly into post_residual,
    // this placement chains perfectly — reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            let slack = post_residual - next_item_size;
            if slack <= 5 {
                score -= 120.0;
            } else if slack <= 15 {
                score -= 40.0;
            } else {
                // Penalize leaving a gap the next item cannot fill well.
                score += slack as f64 * 0.5;
            }
        } else {
            // Next item doesn't fit here; dead space relative to next item.
            let gap = next_item_size - post_residual;
            if gap <= 5 {
                score += 10.0;
            } else {
                score += gap as f64 * 0.8;
            }
        }
    }

    // Compare against mean residual: bins below mean residual are more "loaded";
    // prefer filling already-low-residual bins to consolidate.
    score += (bin_residual as f64 - mean_residual) * 0.6;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current
    // residuals are all poor fits (large post_residual waste).
    if bin_residual == bin_capacity {
        score += 30.0;
        // If lookahead chains well in a fresh bin (e.g., item + next ≈ capacity), allow it.
        if next_item_size > 0 && (item_size + next_item_size) as f64 >= bin_capacity as f64 * 0.95 {
            score -= 90.0;
        }
        // Late in the stream, opening fresh bins is cheaper than fragmenting.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if post_residual as f64 > mean_residual + 20.0 {
            score -= 40.0 * progress;
        }
    }

    // Mild preference to spread across many open bins when they are plentiful.
    score += open_bins_count as f64 * 0.15;

    score
}

