    let mut score = post;

    // Reward exact closure, especially when many bins are already open.
    if post_residual == 0 {
        score -= cap * (0.22 + 0.28 * open_pressure + 0.10 * progress);
    }

    // Strict dead-space avoidance: penalize nonzero gaps below the lookahead
    // size, or below a small generic usability threshold.
    let dead_limit = next.max(0.10 * cap);
    if post > 0.0 && post < dead_limit {
        let missing = dead_limit - post;
        let dead_weight = 2.2 + 1.2 * open_pressure + 0.6 * progress + 0.4 * mean_norm;
        score += missing * dead_weight;
    }

    // Breaking the immediate lookahead chain is a serious fragmentation cost.
    if next > 0.0 && post > 0.0 && post < next {
        score += cap * (0.45 + 0.35 * (1.0 - post / next));
    }

    // Reward placements that leave just enough room for the next item.
    if next > 0.0 && post >= next {
        let tightness = 1.0 - ((post - next) / cap).clamp(0.0, 1.0);
        score -= cap * (0.18 + 0.07 * progress) * tightness;
    }

    // Pressure against opening another bin when useful open bins exist.
    if is_new_bin {
        let fit_pressure = fitting.min(4.0);
        let mut new_penalty = cap
            * (0.18 + 0.45 * open_pressure + 0.10 * mean_norm + 0.05 * fit_pressure)
            * (1.10 - 0.25 * item_norm);

        // A new bin that cannot absorb the next item is especially wasteful.
        if next > 0.0 && post < next {
            new_penalty += cap * (0.70 + 0.25 * (1.0 - post / next));
        }

        score += new_penalty;
    } else if fitting_bins_count == 1 {
        // Strongly prefer the last open bin that can still take the item.
        score -= cap * (0.20 + 0.30 * open_pressure + 0.05 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity.max(1) as f64;
    let post = post_residual as f64;
    let next = next_item_size as f64;
    let open = open_bins_count as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let mean_norm = (mean_residual / cap).clamp(0.0, 1.0);
    let item_norm = (item_size as f64 / cap).clamp(0.0, 1.0);
    let open_pressure = open / (open + 5.0);
    let is_new_bin = bin_residual == bin_capacity;

    let mut score = post;

    // Tight fit reward: squared fit ratio discount.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Exact closure bonus, stronger when many bins are open.
    if post_residual == 0 {
        score -= cap * (0.20 + 0.30 * open_pressure + 0.10 * progress);
    }

    // Dead-space avoidance: gaps below lookahead or a small usability floor.
    let dead_limit = next.max(0.10 * cap);
    if post > 0.0 && post < dead_limit {
        let missing = dead_limit - post;
        let dead_weight = 2.0 + 1.2 * open_pressure + 0.6 * progress + 0.4 * mean_norm;
        score += missing * dead_weight;
    }

    // Breaking the lookahead chain is costly fragmentation.
    if next > 0.0 && post > 0.0 && post < next {
        score += cap * (0.40 + 0.35 * (1.0 - post / next));
    }

    // Reward leaving just enough room for the next item.
    if next > 0.0 && post >= next {
        let tightness = 1.0 - ((post - next) / cap).clamp(0.0, 1.0);
        score -= cap * (0.15 + 0.08 * progress) * tightness;
    }

    // Last-chance bonus: only bin that fits.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= cap * (0.20 + 0.30 * open_pressure + 0.05 * progress);
    }

    // New-bin decision: penalize unless residuals are truly unusable.
    if is_new_bin {
        let fit_pressure = fitting_bins_count.min(4) as f64;
        let mut new_penalty = cap
            * (0.18 + 0.45 * open_pressure + 0.10 * mean_norm + 0.05 * fit_pressure)
            * (1.10 - 0.25 * item_norm);
        if next > 0.0 && post < next {
            new_penalty += cap * (0.60 + 0.25 * (1.0 - post / next));
        }
        // Early stream with large items may justify a fresh bin.
        if progress < 0.15 && item_norm > 0.6 {
            new_penalty -= cap * 0.25;
        }
        score += new_penalty;
    } else {
        // Consolidate waste: prefer bins below mean residual.
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        }
        if post_residual >= 10 {
            score -= 3.0;
        } else {
            score += 6.0;
        }
    }

    // Late-stream tightening.
    score *= 1.0 + 0.25 * progress * (bin_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual gets extra discount.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space that cannot hold the lookahead item (if any).
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 12.0 * (next_item_size - post_residual) as f64;
        } else {
            score -= 8.0; // lookahead item can still fit here
        }
    } else {
        // Last item: prefer filling bins as tightly as possible.
        score -= 20.0 * fit_ratio;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize opening new bins when many bins are already open and fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / bin_capacity as f64;
        // New bin is attractive only if existing residuals are tiny and we're early.
        score += 40.0 * fragmentation * (1.0 - 0.5 * progress);
        score += 5.0 * open_bins_count as f64;
        // If nothing fits well (large post_residual elsewhere), new bin less penalized.
        if post_residual >= 60 {
            score -= 10.0;
        }
    } else {
        // Mild bonus for using bins whose residual is below mean (consolidate waste).
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        }
        // Slight preference for bins that leave residuals in "usable" ranges (>= next item or >= 10).
        if post_residual >= 10 {
            score -= 3.0;
        } else {
            score += 6.0; // creating tiny unusable slivers
        }
    }

    // Time-horizon coupling: later in the stream, tighten up and avoid new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead matching
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect 2-step match: item + next item fill bin exactly
            score -= 1000.0;
        } else if post_residual > next_item_size {
            // Next item still fits after this placement; reward tightness
            let slack = (post_residual - next_item_size) as f64;
            score -= 200.0 - slack * 1.5;
        } else {
            // Next item cannot follow into this bin: penalize dead space
            let dead = (next_item_size - post_residual) as f64;
            score += dead * 2.0;
        }
    } else {
        // Last item: prefer minimal final residual
        score += post_residual as f64 * 0.5;
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= (mean_residual - post_residual as f64) * 1.0;

    // Last chance bin: if this is the only bin that fits, strongly favor it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // New empty bin candidate: penalize unless nothing reasonable fits
    if bin_residual == bin_capacity {
        score += 150.0;
        // Early in stream, opening new bins is cheaper (more future flexibility)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= progress * 100.0;
    }

    // Mild penalty for leaving small unusable fragments
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    score
}

