        else if pr < 20 { score += 18.0; }
        else if pr < 30 { score += 6.0; }

        // Fractional capacity thresholds: post_residual as fraction of capacity
        let frac = pr as f64 / bin_capacity as f64;
        if frac < 0.10 { score += 25.0; }
        else if frac > 0.60 { score -= 10.0; } // big leftover is flexible
    }

    // --- Lookahead coupling: harmonic class of next_item_size ---
    if next_item_size > 0 {
        if next_item_size <= pr {
            // next item fits exactly-ish: strong reward, especially if it
            // would zero out the bin (harmonic match mod 10)
            score -= 18.0;
            if next_item_size == pr { score -= 30.0; }
            else if pr % 10 == 0 && next_item_size % 10 == 0 { score -= 6.0; }
        } else {
            // next item cannot use this bin's leftover: penalize small leftovers
            let gap = (next_item_size - pr) as f64;
            score += (gap / 10.0).min(15.0);
        }
    } else {
        // last item: prefer filling bins as tightly as possible
        score -= 10.0;
    }

    // --- Last-chance bonus: only this bin fits -> avoid opening a new bin ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when the item is large and
        // existing residuals are poor fits (mean residual too small).
        score += 70.0; // base penalty: prefer reusing open bins
        let mean_ok = mean_residual >= item_size as f64 + 5.0;
        if mean_ok { score += 30.0; } // open bins still have room, don't open new
        if item_size >= 60 && mean_residual < 40.0 { score -= 55.0; } // big item, crowded bins
        if open_bins_count == 0 { score -= 100.0; } // must open a bin
        if next_item_size > 0 && next_item_size >= item_size && mean_residual < next_item_size as f64 {
            score -= 20.0; // lookahead suggests fresh capacity is valuable
        }
    }

    // --- Stream progression: late in the stream, close bins tightly ---
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (pr % 10 == 0) as i32 as f64;

    // Mild preference to keep the number of open bins bounded
    if open_bins_count > 8 && bin_residual != bin_capacity {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: perfect placement, strongly reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: any leftover gap below the minimum item
    // size (1..10) is unusable for most items -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 500.0;
    } else if post_residual < 20 {
        // Small but potentially usable gaps: moderate penalty scaled by gap size.
        score += (20.0 - post_residual as f64) * 20.0;
    }

    // Penalize creating gaps that the lookahead item cannot use.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 120.0;
    }
    // Reward gaps that exactly accommodate the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 80.0;
    }

    // Open-bins pressure: discourage spreading across many bins when
    // alternatives exist; encourage consolidating into fewer bins.
    if fitting_bins_count > 1 && bin_residual != bin_capacity {
        score -= 15.0 * (fitting_bins_count as f64 - 1.0).min(3.0);
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: only attractive if all open bins would create
    // dead space (post_residual small but nonzero) or open set is huge.
    if bin_residual == bin_capacity {
        let dead_space_risk = (post_residual > 0 && post_residual < 10) as i32 as f64;
        score += 60.0 - 30.0 * dead_space_risk
               + 2.0 * open_bins_count as f64
               - 0.5 * mean_residual;
    }

    // Mild stream-progression tiebreak: later in stream, prefer tighter fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.5;

    // Deviation from mean residual: prefer bins whose post placement moves
    // residual close to the fleet mean (balance).
    score += 0.3 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, penalize dead space relative to capacity.
    score += 0.35 * (post_residual as f64 / bin_capacity as f64) * 100.0;

    // 2-step lookahead: if the next item fits exactly in post_residual, strongly reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let perfect = (post_residual - next_item_size) as f64;
        score -= 40.0 * (1.0 - perfect / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize leaving large residual that wastes space.
        score += 0.25 * post_residual as f64;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Prefer bins whose residual deviates favorably from the mean residual
    // (place into bins with below-average residual to consolidate space).
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Reward using existing bins vs opening new ones as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 5.0 + 10.0 * progress;
    } else {
        // New-bin candidate: only attractive when post_residual (== capacity - item)
        // leaves a useful remainder and few open bins exist.
        score += 20.0 * progress;
        if open_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Small exact-fit reward for current item.
    if post_residual == 0 {
        score -= 60.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual gets extra discount.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space that cannot hold the lookahead item (if any).
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 12.0 * (next_item_size - post_residual) as f64;
        } else {
            score -= 8.0; // lookahead item can still fit here
        }
    } else {
        // Last item: prefer filling bins as tightly as possible.
        score -= 20.0 * fit_ratio;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize opening new bins when many bins are already open and fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / bin_capacity as f64;
        // New bin is attractive only if existing residuals are tiny and we're early.
        score += 40.0 * fragmentation * (1.0 - 0.5 * progress);
        score += 5.0 * open_bins_count as f64;
        // If nothing fits well (large post_residual elsewhere), new bin less penalized.
        if post_residual >= 60 {
            score -= 10.0;
        }
    } else {
        // Mild bonus for using bins whose residual is below mean (consolidate waste).
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        }
        // Slight preference for bins that leave residuals in "usable" ranges (>= next item or >= 10).
        if post_residual >= 10 {
            score -= 3.0;
        } else {
            score += 6.0; // creating tiny unusable slivers
        }
    }

    // Time-horizon coupling: later in the stream, tighten up and avoid new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Non-linear polynomial coupling: residual squared scaled by progress
    score -= 40.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits more as stream progresses (cubic coupling)
    let tightness = 1.0 - norm_pr;
    score -= 30.0 * tightness * tightness * tightness * progress;

    // Penalize dead space relative to mean residual (quadratic divergence)
    let dev = pr - mean_residual;
    score += 0.15 * dev * dev / cap;

    // Last-chance bin bonus (smooth exponential rather than hard switch)
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead coupling: prefer bins whose post-residual can fit next item
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr >= n {
            let slack = (pr - n) / cap;
            score -= 20.0 * (1.0 - slack * slack);
        } else {
            score += 10.0 * (n - pr) / cap;
        }
    }

    // New-bin candidate: penalize mildly so open bins are preferred unless very poor fits
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * progress;
    }

    // Slight pressure to consolidate when many bins are open
    score += 0.5 * open_bins_count as f64 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual divisible by common item
    // granularities (10, 5) is reusable; tiny odd residuals are dead space.
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 {
            score -= 8.0; // highly reusable class
        } else if pr % 5 == 0 {
            score -= 4.0;
        } else if pr < 10 {
            score += 12.0; // dead space below min item size
        } else {
            score += 3.0; // awkward remainder
        }
    } else {
        score -= 20.0; // perfect closure
    }

    // Lookahead coupling: does next item fit exactly or well into post_residual?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0; // perfect pair
        } else if next_item_size <= pr {
            let slack = pr - next_item_size;
            score -= 10.0 - slack as f64 * 0.15;
            if slack % 10 == 0 { score -= 4.0; }
        } else {
            // next item cannot use this residual: penalize proportionally
            score += ((next_item_size - pr) as f64) * 0.25;
        }
    }

    // Integer-division threshold: residual in "large" half of capacity is valuable
    let half = bin_capacity / 2;
    if pr >= half {
        score -= 6.0;
    } else if pr >= half / 2 {
        score += 1.0;
    } else if pr > 0 {
        score += 5.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when current bin would leave tiny waste
    // or when stream is early and spreading capacity is cheap.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 45.0 + progress * 30.0 - (open_bins_count as f64) * 0.5;
        if pr == bin_capacity { /* unreachable guard */ }
    }

    // Prefer tighter bins overall relative to mean residual of open bins
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    } else {
        score += 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps (< 10, unusable range)
    // are the worst outcome; penalize them heavily and nonlinearly.
    if post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 4.0;
    } else if post_residual <= 20 {
        // Small-but-usable gaps are risky: only next items <= gap can use them.
        score += 12.0 * (1.0 - (post_residual as f64 / 20.0));
    }

    // Reward tight fits (post_residual close to 0 but still >= 10).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 15.0 * tightness * tightness;

    // Open-bin pressure: when many bins are open, prefer consolidating
    // into existing bins rather than spreading out.
    score += (open_bins_count as f64) * 1.5;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin has huge post_residual, which
    // already scores well. Penalize it mildly so a decent existing fit wins,
    // but the penalty is overridden when the item leaves a bad gap elsewhere.
    if bin_residual == bin_capacity {
        score += 20.0;
        // If the item would leave a large residual in a new bin, opening is
        // attractive for future flexibility; ease the penalty.
        if post_residual >= 40 {
            score -= 10.0;
        }
    }

    // Lookahead: if the next item fits exactly into the post_residual,
    // this placement sets up a perfect follow-up; reward it.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 5.0;
    }

    // Mean-residual coupling: if the bin is much emptier than average,
    // filling it is efficient; if much emptier space remains than average,
    // slight penalty to avoid hoarding capacity.
    if post_residual as f64 > mean_residual * 1.5 {
        score += 6.0;
    } else if (post_residual as f64) < mean_residual * 0.5 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good (already base score).
    // Strong reward when the lookahead item fits exactly into the post residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 - slack.min(40.0);
        // Perfect chain fit bonus
        if slack == 0.0 {
            score -= 25.0;
        }
    } else if next_item_size > 0 {
        // Lookahead item won't fit here: penalize proportionally to the mismatch,
        // but less if the leftover is large enough to be reusable.
        let gap = (next_item_size - post_residual) as f64;
        score += 0.6 * gap.min(60.0);
    }

    // Compare post residual against mean residual of open bins:
    // leaving a post residual near the mean keeps the bin pool balanced.
    let pr = post_residual as f64;
    let dev = (pr - mean_residual).abs();
    score += 0.15 * dev;

    // Penalize creating tiny unusable dead space (waste).
    if pr > 0 && pr < 10.0 {
        score += 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Mild penalty for spreading across many open bins early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count as f64 > 2.0 + 8.0 * progress {
        score += 2.0;
    }

    // New-bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        score += 15.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // fresh bin gives room for the larger lookahead item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: minimize post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize dead space that can never be reused by typical items.
    if post_residual > 0 {
        let dead = if post_residual < 10 { 0.0 } else { (post_residual as f64 - 10.0) / (bin_capacity as f64) };
        score += 25.0 * dead * dead;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward strongly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let next_tight = (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 18.0 * (1.0 - next_tight);
        } else {
            // Post-residual too small for next item: penalize proportional to waste.
            score += 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Encourage consolidation when many bins are open: prefer bins with low residual.
    let open_factor = (open_bins_count as f64).ln().max(1.0);
    score += open_factor * (bin_residual as f64 / bin_capacity as f64) * 6.0;

    // Global state coupling: if mean residual is high, prefer filling bins down further.
    score -= 5.0 * (mean_residual / bin_capacity as f64) * tightness;

    // Time horizon: early in the stream, be more open to opening new bins (explore);
    // late in the stream, pack tightly into existing bins (exploit).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 10.0 * (post_residual as f64 / bin_capacity as f64);
    score -= progress * 12.0 * tightness;

    // Prefer keeping residuals aligned with common item sizes (multiples of 10).
    let r = post_residual % 10;
    if r != 0 && post_residual > 0 {
        score += 3.0 * (r.min(10 - r) as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Normalized post-residual (dead-space fraction) and its non-linear shape
    let x = post / cap;                       // 0..1
    let dead_space_cost = x * x * (3.0 - 2.0 * x); // smoothstep: punishes large residuals smoothly

    // Non-linear coupling of post-residual with stream progress:
    // late in the stream, tight fills matter more; early on, keep bins flexible.
    let tightness = 1.0 - (post / cap).powf(1.0 + 2.0 * progress); // small post => tightness ~1
    let progress_coupling = progress * tightness * (item / cap);

    // Fit quality: how well item fills the bin, smoothly weighted
    let fill = item / cap;
    let fill_reward = fill * fill * (1.0 + progress);

    // Last-chance bonus: avoid opening a new bin when this is the only fitting one
    let last_chance = if fitting_bins_count == 1 && bin_residual != bin_capacity { -0.35 } else { 0.0 };

    // Lookahead: reward if next item fits the post-residual, penalize otherwise
    let lookahead = if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post { -0.15 * (nxt / cap) * (1.0 - progress) } else { 0.20 * (nxt / cap) * (0.5 + progress) }
    } else { 0.0 };

    // Slight penalty when this bin's residual deviates from mean residual (spread control)
    let spread_penalty = ((post - mean_residual) / cap).abs() * 0.10;

    // New-bin candidate: neutral baseline with mild early-stream openness
    let new_bin_bias = if bin_residual == bin_capacity { 0.05 + 0.25 * (1.0 - progress) } else { 0.0 };

    let mut score = dead_space_cost * cap * 0.5
        - progress_coupling * cap
        - fill_reward * cap
        + spread_penalty * cap
        + last_chance * cap
        + lookahead * cap
        + new_bin_bias * cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual modulo capacity/10 (i.e., 10).
    let class = post_residual % 10;
    // Residuals that are multiples of 10 are more reusable for typical item sizes.
    score -= (10 - class) as f64 * 0.5;

    // Penalize small dead space that nothing can fit into (below min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Reward leaving room for the lookahead item (k=2).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // Lookahead won't fit here; penalize proportionally to how close we were.
            score += (next_item_size - post_residual) as f64 * 0.6;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Penalize opening a new bin when existing bins fit, scaled by stream progress.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 80.0 + 40.0 * progress;
    }

    // Mild penalty for bins far below the mean residual (fragmentation avoidance).
    score += ((mean_residual - post_residual as f64).abs()) * 0.2;

    // Integer-division threshold: bins with residual >= half capacity are flexible.
    if post_residual >= bin_capacity / 2 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    let cap = bin_capacity.max(1) as f64;
    let post = post_residual as f64;
    let next = next_item_size as f64;
    let open = open_bins_count as f64;
    let fitting = fitting_bins_count as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let mean_norm = (mean_residual / cap).clamp(0.0, 1.0);
    let item_norm = (item_size as f64 / cap).clamp(0.0, 1.0);
    let open_pressure = open / (open + 5.0);
    let is_new_bin = bin_residual == bin_capacity;

    let mut score = post;

    // Reward exact closure, especially when many bins are already open.
    if post_residual == 0 {
        score -= cap * (0.22 + 0.28 * open_pressure + 0.10 * progress);
    }

    // Strict dead-space avoidance: penalize nonzero gaps below the lookahead
    // size, or below a small generic usability threshold.
    let dead_limit = next.max(0.10 * cap);
    if post > 0.0 && post < dead_limit {
        let missing = dead_limit - post;
        let dead_weight = 2.2 + 1.2 * open_pressure + 0.6 * progress + 0.4 * mean_norm;
        score += missing * dead_weight;
    }

    // Breaking the immediate lookahead chain is a serious fragmentation cost.
    if next > 0.0 && post > 0.0 && post < next {
        score += cap * (0.45 + 0.35 * (1.0 - post / next));
    }

    // Reward placements that leave just enough room for the next item.
    if next > 0.0 && post >= next {
        let tightness = 1.0 - ((post - next) / cap).clamp(0.0, 1.0);
        score -= cap * (0.18 + 0.07 * progress) * tightness;
    }

    // Pressure against opening another bin when useful open bins exist.
    if is_new_bin {
        let fit_pressure = fitting.min(4.0);
        let mut new_penalty = cap
            * (0.18 + 0.45 * open_pressure + 0.10 * mean_norm + 0.05 * fit_pressure)
            * (1.10 - 0.25 * item_norm);

        // A new bin that cannot absorb the next item is especially wasteful.
        if next > 0.0 && post < next {
            new_penalty += cap * (0.70 + 0.25 * (1.0 - post / next));
        }

        score += new_penalty;
    } else if fitting_bins_count == 1 {
        // Strongly prefer the last open bin that can still take the item.
        score -= cap * (0.20 + 0.30 * open_pressure + 0.05 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post-residual, but weight by stream progression.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.5 * progress;

    // 2-step lookahead: reward when the NEXT item fits exactly into post_residual.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if (post_residual as f64 - next).abs() < 0.5 {
            // Perfect chain fit: strongly reward.
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item still fits: mild reward proportional to tightness.
            let tightness = 1.0 - (post_residual as f64 - next) / bin_capacity as f64;
            score -= 20.0 * tightness;
        } else {
            // Next item cannot fit: dead-space penalty scaled by wasted gap.
            let gap = (next - post_residual as f64).min(bin_capacity as f64);
            score += 0.4 * gap;
        }
    }

    // Compare post_residual against mean residual: leaving far-above-average
    // residual creates fragmented bins.
    let pr = post_residual as f64;
    if pr > mean_residual {
        score += 0.3 * (pr - mean_residual);
    } else {
        score -= 0.2 * (mean_residual - pr);
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // heavily favor using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // New-bin candidate handling: an empty bin has no fragmentation cost,
    // but discourage opening new bins when a tight fit exists elsewhere.
    if bin_residual == bin_capacity {
        score += 10.0 + 0.1 * open_bins_count as f64;
        if next_item_size > 0 && post_residual >= next_item_size {
            score += 15.0; // empty bin chains well, slight extra appeal
        }
    }

    // Tiny tight-fit nudge: near-perfect fills are always good.
    if post_residual <= 2 {
        score -= 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual relative to capacity is good.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 25.0 * tightness;

    // Penalize dead space that is too small to be useful for typical items (1..100).
    if post_residual > 0 {
        let pr = post_residual as f64;
        if pr < 10.0 {
            score += 30.0; // nearly unusable sliver
        } else {
            // Usability curve: residuals that fit mid-size items are valuable.
            let usable = if pr >= 50.0 { 1.0 } else { pr / 50.0 };
            score -= 15.0 * usable;
        }
    }

    // Lookahead: if the next item fits exactly-ish into post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let leftover = post_residual - next_item_size;
        let fit_quality = 1.0 - (leftover as f64) / (bin_capacity as f64);
        score -= 20.0 * fit_quality;
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item can't use the remaining space: penalize proportionally.
        score += 8.0 * (1.0 - (next_item_size as f64 - post_residual as f64) / (next_item_size as f64).max(1.0));
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when current
    // bins are crowded or the fit here is terrible.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 40.0;
        // Cheaper to open new bins early in the stream (more future items to amortize).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
        // If many open bins have large mean residual, prefer spreading load.
        score -= (mean_residual / bin_capacity as f64).min(1.0) * 10.0;
    } else {
        // Using an existing bin: reward more when open bins are plentiful.
        score -= (open_bins_count as f64).min(20.0) * 0.5;
    }

    // Mild global pressure: as stream progresses, discourage fragmenting residuals.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Coupling: if this bin's residual deviates strongly from mean residual,
    // slightly prefer bins tighter than the mean (consolidation).
    let dev = (bin_residual as f64 - mean_residual) / (bin_capacity as f64);
    score += 5.0 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth non-linear polynomial coupling of post_residual with stream progress.
    let mut score = pr;

    // Early stream: prefer tight fits mildly; late stream: punish residual strongly.
    let progress_weight = 0.5 + 2.0 * progress * progress;
    score += progress_weight * norm_pr * cap * 0.5;

    // Cubic penalty for residual that is likely dead space (small but nonzero),
    // smoothed via polynomial in normalized residual.
    let dead = norm_pr * norm_pr * (1.0 - norm_pr);
    score += 60.0 * dead * (1.0 + progress);

    // Reward exact/near-exact fits smoothly (post residual near 0).
    score -= 30.0 * (-norm_pr * 20.0).exp() * (0.5 + progress);

    // Lookahead coupling: if next item fits the post residual, reward smoothly.
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 15.0 * (-gap * gap / (cap * cap)).exp();
    }

    // Last-chance bin: strong reward to use it rather than open a new one.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress * 0.5);
    }

    // Mean residual coupling: penalize bins far from the mean residual
    // (smooth quadratic deviation) to keep the pool balanced.
    let dev = (pr - mean_residual) / cap;
    score += 10.0 * dev * dev * cap * 0.1;

    // New-bin candidate handling: make an empty bin attractive only when
    // residuals across open bins are low or progress is early.
    if bin_residual == bin_capacity {
        let pool_tight = (-mean_residual / cap).exp();
        score = pr - 20.0 * pool_tight * (1.0 - progress) + 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual into residue classes mod 10.
    // Residues that are "dead" (small, hard to fill) should be penalized.
    let r = post_residual % 10;
