        1..=3 => 12.0 + (3 - r) as f64 * 4.0, // tiny slivers: worst dead space
        4..=6 => 4.0,                     // mediocre
        7..=9 => -6.0 + (9 - r) as f64,   // near-aligned, decent
        _ => 0.0,
