    // (in units of a common small item) can still fit?
    let usable_slots = post_residual / 10;
    score -= (usable_slots as f64).powi(2) * 2.0; // reward residual that can host many small items

    // Capacity fraction coupling: penalize leaving residual in awkward fractions of capacity.
    let frac = post_residual as f64 / bin_capacity as f64;
    if frac < 0.10 {
        score += 25.0 * (0.10 - frac); // near-empty bin: wasted capacity
    } else if frac > 0.5 {
        score -= 10.0 * (frac - 0.5); // bins still over half-full are valuable targets
    }

    // Lookahead harmonic match: does next_item_size divide nicely into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let gap = post_residual - next_item_size;
            // Reward exact / harmonic fits for the next item
            let gap_mod = gap % 10;
            if gap == 0 {
                score -= 60.0; // perfect chained fit
            } else if gap_mod == 0 {
                score -= 25.0; // aligned chained fit
            } else if gap < 10 {
                score += 15.0; // creates new dead sliver for next item
            }
            score -= (gap as f64).sqrt() * 3.0; // mild reward for roomy continuation
        } else {
            // next item cannot fit here: this bin is terminal after current item
            score += 8.0;
        }
    }

    // Last-chance logic: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless post_residual would be a horrible sliver).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
        if post_residual > 0 && post_residual < 10 {
            score -= 10.0; // still fine: we eliminated the bin entirely
        }
    }

    // New-bin candidate handling: empty bin should only win when open bins are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Penalize new bins generally; relax penalty as stream progresses or bins fragment.
        let fragmentation = (mean_residual - post_residual as f64).abs() / bin_capacity as f64;
        score += 45.0 - 20.0 * progress - 15.0 * fragmentation;
        // A new bin is attractive for very large items (they ruin any bin).
        if item_size >= 70 {
            score -= 20.0;
