    let item_norm = (item_size as f64 / cap).clamp(0.0, 1.0);
    let open_pressure = open / (open + 5.0);
    let is_new_bin = bin_residual == bin_capacity;

    let mut score = post;

    // Tight fit reward: squared fit ratio discount.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Exact closure bonus, stronger when many bins are open.
    if post_residual == 0 {
        score -= cap * (0.24 + 0.30 * open_pressure + 0.10 * progress);
    }

    // Dead-space avoidance: gaps below lookahead or a small usability floor.
    let dead_limit = next.max(0.10 * cap);
    if post > 0.0 && post < dead_limit {
        let missing = dead_limit - post;
        let dead_weight = 2.4 + 1.3 * open_pressure + 0.6 * progress + 0.5 * mean_norm;
        score += missing * dead_weight;
    }

    // Breaking the lookahead chain is costly fragmentation.
    if next > 0.0 && post > 0.0 && post < next {
        score += cap * (0.45 + 0.35 * (1.0 - post / next));
    }

    // Reward leaving just enough room for the next item.
    if next > 0.0 && post >= next {
        let slack = ((post - next) / cap).clamp(0.0, 1.0);
        let tightness = 1.0 - slack * slack;
        score -= cap * (0.18 + 0.07 * progress) * tightness;
        // Near-exact multiple of next item: chain-friendly residual.
        let ratio = post / next;
        let mult_err = (ratio - ratio.round()).abs();
        if mult_err < 0.02 {
            score -= cap * 0.06 * (1.0 - 0.5 * progress);
        }
    }

    // Tiny unusable gap penalty.
    if post > 0.0 && next > 0.0 && post < next && post < 0.06 * cap {
        score += cap * (0.15 + 0.20 * progress);
    }

    // Last-chance bonus: only bin that fits.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= cap * (0.20 + 0.30 * open_pressure + 0.05 * progress);
    } else if !is_new_bin && next > 0.0 {
        // Chain alignment: penalize residuals poorly aligned with next item multiples.
        let ratio = post / next;
        let chain_fit = (ratio.round() - ratio).abs();
        let chain_weight = 0.06 + 0.02 * fitting.min(5.0);
        score += chain_fit * next * chain_weight;
    }

    // New-bin decision: penalize unless residuals are truly unusable.
    if is_new_bin {
        let fit_pressure = fitting.min(4.0);
        let mut new_penalty = cap
            * (0.18 + 0.45 * open_pressure + 0.10 * mean_norm + 0.05 * fit_pressure)
            * (1.10 - 0.25 * item_norm);
        if next > 0.0 && post < next {
            new_penalty += cap * (0.70 + 0.25 * (1.0 - post / next));
        }
        // Late stream: opening bins is wasteful.
        new_penalty += cap * 0.10 * progress;
        // Very large items early may justify a fresh bin.
        if item_norm > 0.90 {
            new_penalty -= cap * 0.35 * (item_norm - 0.90) / 0.10;
        }
        score += new_penalty;
    } else {
        // Consolidate waste: prefer bins below mean residual.
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        }
        if post_residual >= 10 {
            score -= 3.0;
        } else {
            score += 6.0;
        }
    }

