    // when few alternative bins compete.
    if !is_new_bin && post > 0.0 {
        let fill_after = 1.0 - post / cap;
        score -= fill_after * cap * 0.06 * (1.0 - fitting.min(3.0) / 3.0);
    }

    // Residual-match bonus: when post exactly equals next, the lookahead
    // chain continues perfectly; reward beyond the tightness term.
    if !is_new_bin && next > 0.0 && post == next {
        score -= cap * 0.05 * (1.0 - progress);
    }

    score
