pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for the smallest
    // plausible future item (<= 10) are pure waste; penalize them heavily.
    if post_residual < 10 && post_residual > 0 {
        score += 60.0;
    }
    // Gaps that can only fit tiny items are near-waste; soft penalty.
    if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Perfect fit: zero dead space is ideal.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no good fit exists among open
    // bins, i.e. when the best possible placement still leaves a dead gap.
    if bin_residual == bin_capacity {
        // Neutral baseline slightly above a decent existing fit.
        score += 20.0;
        // Opening new bins is costly when many bins are already open.
        score += open_bins_count as f64 * 2.0;
        // But if placing here would strand a tiny gap in an existing bin,
        // a fresh bin becomes attractive instead.
        if post_residual < 10 && post_residual > 0 {
            score -= 70.0;
        }
        // Late in the stream, avoid proliferating bins that end mostly empty.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
    }

    // Prefer bins whose residual is close to the mean (keep residuals uniform,
    // consolidating waste into few bins rather than spreading it).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.3;

    // Lookahead: if the next item fits exactly in the post-residual, reward it.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    }
    // If next item would not fit here afterwards, mild penalty for chaining risk.
    if next_item_size > post_residual && next_item_size <= bin_residual {
        score += 4.0;
    }

    score
}

pub fn score_bin(
