pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly fits the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Near-match bonus: next item fits with small slack (tight 2-step chain).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 300.0 / (1.0 + slack);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space relative to lookahead: next item cannot chain here.
        let dead = (next_item_size - post_residual) as f64;
        score += dead * 2.0;
    }

    // Penalize post_residual falling below the minimum item size (unusable gap),
    // scaled by how much worse it is than the average open-bin residual.
    if post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0;
    }

    // Prefer keeping residuals near the mean (balance), mild weight.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.5;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: score it as a neutral baseline (post_residual = capacity).
    // Penalize opening a new bin when existing bins fit well, reward it when
    // the current bin's post-fit is poor for the lookahead.
    if bin_residual == bin_capacity {
        score += 40.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 50.0; // fresh bin chains well with lookahead
        }
    }

    // Late in the stream, tighten up: avoid leaving many small open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic penalty on wasted space.
    let waste_frac = post_residual as f64 / cap;
    score += 40.0 * waste_frac * waste_frac;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: penalize opening a new bin, but less when
    // existing bins are crowded (mean residual small) or late in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowding = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        let mut penalty = 25.0 + 35.0 * crowding - 15.0 * progress;
        // If next item could pair into this fresh bin's leftover, soften penalty.
        if next_item_size > 0 && (post_residual as i64 - next_item_size as i64) >= 0 {
            penalty -= 10.0;
        }
        score += penalty.max(0.0);
    } else {
        // Lookahead chaining: reward bins whose post-residual can host the next item.
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                let snug = 1.0 - ((post_residual - next_item_size) as f64 / cap);
                score -= 8.0 + 12.0 * snug;
            } else {
                // Dead-end for the next item: mild penalty scaled by next size.
                score += 3.0 * (next_item_size as f64 / cap);
            }
        }
        // Favor bins that are already partially filled (consolidation).
        let fill_frac = 1.0 - (bin_residual as f64 / cap);
        score -= 10.0 * fill_frac * fill_frac;
    }

    // Global pressure: with many open bins, discourage spreading; with few, allow it.
    if open_bins_count > 2 {
        score += 0.5 * (open_bins_count as f64).ln();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let progress = progress.clamp(0.0, 1.0);

    let mut score = post;

    // Reward tight fits: smaller post_residual relative to capacity is better,
    // with a smooth quadratic coupling scaled by stream progress.
    let tightness = 1.0 - (post / cap);
    score -= 18.0 * tightness * tightness * (0.5 + 0.5 * progress);

    // Penalize residual far from the range usable by typical items (1..=100):
    // dead space that is too small for anything is wasted; smooth bowl-shaped term.
    let r = post / cap;
    score += 12.0 * (r - 0.35) * (r - 0.35) * (1.0 - progress);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: reward bins whose post residual still fits the next item,
    // penalize bins that would strand the next item.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if post >= ni {
            score -= 6.0 * (1.0 - ((post - ni) / cap));
        } else {
            score += 5.0 * ((ni - post) / cap);
        }
    }

    // New-bin candidate handling: an empty bin has bin_residual == bin_capacity.
    // Give it a mild fixed handicap so existing bins with decent fits win,
    // but it stays attractive when all fits are poor (large post residual there).
    if bin_residual == bin_capacity {
        score += 20.0 + 10.0 * progress;
    }

    // Slight preference to consolidate when many bins are open.
    score += 0.3 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residual modulo capacity fractions
    let pr = post_residual;
    let class_quarter = (pr % (bin_capacity / 4)).max(1) as f64;
    let class_eighth = (pr % (bin_capacity / 8)).max(1) as f64;

    // Penalize residuals in "dead zones": small unusable slivers (< 10, min item)
    if pr > 0 && pr < 10 {
        score += 40.0;
    }
    // Penalize residuals just above common item sizes (wasted near-fit)
    for s in [10u32, 20, 30, 40, 50, 60, 70, 80] {
        if pr > s && pr <= s + 3 {
            score += 6.0;
        }
    }

    // Reward tight fits (small post residual) non-linearly
    score -= 30.0 * (-post_residual as f64 / 8.0).exp();

    // Fraction-of-capacity coupling: prefer filling bins past half
    let fill_frac = (bin_capacity - post_residual) as f64 / cap;
    if fill_frac >= 0.5 {
        score -= 12.0 * fill_frac;
    } else {
        score += 8.0 * (0.5 - fill_frac);
    }

    // Harmonic class interplay with next item lookahead
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0; // perfect pair
        } else if next_item_size < pr {
            score -= 8.0 * (1.0 - (pr - next_item_size) as f64 / cap);
        } else {
            // next item won't fit here: residual becomes dead space
            score += 5.0 + 0.2 * pr as f64;
        }
        // modulo resonance: next_item shares harmonic class with residual
        if next_item_size % (bin_capacity / 8) == pr % (bin_capacity / 8) && pr >= next_item_size {
            score -= 6.0;
        }
    } else {
        // last item: strongly prefer any fit, tightest possible
        score += 0.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize unless open bins are crowded or fit is bad
    if bin_residual == bin_capacity {
        score = cap - item_size as f64;
        if fitting_bins_count == 0 {
            score -= 50.0; // no alternative: must open
        } else {
            // open a new bin only if existing fits are all poor (large post residual)
            score += 10.0;
            if item_size >= 70 {
                score -= 20.0; // big items better in fresh bins
            }
        }
    }

    // Mild pressure to consolidate when many bins are open
    score += 0.05 * open_bins_count as f64 * (1.0 - fill_frac);

    // Mean-residual coupling: prefer bins below mean residual (tighter bins)
    score += 0.1 * (mean_residual - post_residual as f64);

    // Quarter/eighth harmonic class tiebreakers
    score += 0.05 * class_quarter + 0.02 * class_eighth;

    // Stream progression: later in stream, slightly prefer reusing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * progress * (bin_residual < bin_capacity) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to hold any item (min size 1..=100 unknown,
    // assume typical small item ~10) are wasted; penalize the "unusable band" harshly.
    let dead_threshold = 9.0;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 15.0;
    }

    // Reward tight fits (small but usable residual) — perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 12 {
        score -= (12 - post_residual) as f64 * 2.0;
    }

    // Pressure from number of open bins: discourage spreading across many bins,
    // but soften when this bin would otherwise be the last chance.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (2.0 + 6.0 * progress);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when item leaves a large, reusable gap
    // or when all open bins would leave heavy dead space.
    if bin_residual == bin_capacity {
        score += 18.0;
        if post_residual >= 50 {
            score -= 12.0;
        }
    }

    // Lookahead: if next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item cannot use this residual: dead space likely, penalize proportionally
        score += (post_residual as f64) * 0.3;
    }

    // Mild alignment with mean residual: prefer bins whose residual is below average
    // (concentrating usage), keeping some larger-residual bins for big future items.
    score -= (mean_residual - bin_residual as f64) * 0.2;

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    let cap = bin_capacity.max(1) as f64;
    let post = post_residual as f64;
    let next = next_item_size as f64;
    let open = open_bins_count as f64;
    let fitting = fitting_bins_count as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let mean_norm = (mean_residual / cap).clamp(0.0, 1.0);
    let item_norm = (item_size as f64 / cap).clamp(0.0, 1.0);
    let open_pressure = open / (open + 5.0);
    let is_new_bin = bin_residual == bin_capacity;

    let mut score = post;

    // Reward exact closure, scaled by crowding.
    if post_residual == 0 {
        score -= cap * (0.24 + 0.30 * open_pressure + 0.10 * progress);
    }

    // Dead-space avoidance: linear severity with convex boost for thin slivers.
    let dead_limit = next.max(0.10 * cap);
    if post > 0.0 && post < dead_limit {
        let missing = dead_limit - post;
        let mut dead_weight = 2.4 + 1.3 * open_pressure + 0.6 * progress + 0.5 * mean_norm;
        let thinness = 1.0 - post / dead_limit;
        if thinness > 0.7 {
            dead_weight += (thinness - 0.7) * 3.0;
        }
        score += missing * dead_weight;
    }

    // Breaking the immediate lookahead chain is a serious fragmentation cost.
    if next > 0.0 && post > 0.0 && post < next {
        score += cap * (0.45 + 0.35 * (1.0 - post / next));
    }

    // Reward placements that leave just enough room for the next item.
    if next > 0.0 && post >= next {
        let slack = ((post - next) / cap).clamp(0.0, 1.0);
        let tightness = 1.0 - slack * slack;
        score -= cap * (0.18 + 0.07 * progress) * tightness;

        // Exact-multiple chain potential.
        let ratio = post / next;
        let mult_err = (ratio - ratio.round()).abs();
        if mult_err < 0.02 {
            score -= cap * 0.06 * (1.0 - 0.5 * progress);
        }
    }

    // Two-step lookahead: stranded tiny gaps late in the stream.
    if post > 0.0 && next > 0.0 && post < next && post < 0.06 * cap {
        score += cap * (0.15 + 0.20 * progress);
    }

    // Fragmentation-anticipation in the awkward band above next item.
    if !is_new_bin && post > next && next > 0.0 {
        let awkward = (next + mean_residual.min(cap)).min(cap);
        if post < awkward {
            let depth = 1.0 - (awkward - post) / awkward.max(1.0);
            score += cap * 0.08 * depth * (0.5 + 0.5 * progress);
        }
    }

    if is_new_bin {
        let fit_pressure = fitting.min(4.0);
        let mut new_penalty = cap
            * (0.18 + 0.45 * open_pressure + 0.10 * mean_norm + 0.05 * fit_pressure)
            * (1.10 - 0.25 * item_norm);

        // A new bin that cannot absorb the next item is especially wasteful.
        if next > 0.0 && post < next {
            new_penalty += cap * (0.70 + 0.25 * (1.0 - post / next));
        }

        new_penalty += cap * 0.10 * progress;

        // Relax penalty when current bins are already highly fragmented.
        new_penalty *= 1.0 - 0.15 * (1.0 - mean_norm) * open_pressure;

        // Opening is attractive when the item nearly fills a fresh bin.
        if item_norm > 0.90 {
            new_penalty -= cap * 0.35 * (item_norm - 0.90) / 0.10;
        }

        // Extra: opening is also attractive when item_norm is moderately large
        // and no existing bin leaves a usable residual for the next item.
        if item_norm > 0.75 && fitting > 0.0 && next > 0.0 {
            let worst_gap = (0.10 * cap).max(next);
            if bin_residual < worst_gap as u32 {
                new_penalty -= cap * 0.12 * (item_norm - 0.75) / 0.25;
            }
        }

        score += new_penalty;
    } else if fitting_bins_count == 1 {
        // Strongly prefer the last open bin that can still take the item.
        score -= cap * (0.20 + 0.30 * open_pressure + 0.05 * progress);
    } else if next > 0.0 {
        // Chain-fit preference: reward residuals close to a multiple of next.
        let ratio = post / next;
        let chain_fit = (ratio.round() - ratio).abs();
        let chain_weight = 0.06 + 0.02 * fitting.min(5.0);
        score += chain_fit * next * chain_weight;
    }

    // Prefer bins whose residual stays usable for the average remaining item.
    if !is_new_bin && post > 0.0 && mean_residual > 0.0 {
        let usable = (post / mean_residual).clamp(0.0, 4.0);
        score += (2.0 - usable).abs() * 0.05 * cap * (1.0 - progress);
    }

    // Compaction reward: prefer the fullest bins after placement.
    if !is_new_bin && post > 0.0 {
        let fill_after = 1.0 - post / cap;
        score -= fill_after * cap * 0.05 * (1.0 - fitting.min(3.0) / 3.0);
    }

    // Residual-parity coupling: post residual + mean residual forming a
    // future exact fit within capacity is rewarded.
    if !is_new_bin && post > 0.0 && mean_residual > 1.0 {
        let pair = post + mean_residual;
        let pair_err = (pair / cap - (pair / cap).round()).abs();
        if pair_err < 0.03 && pair <= cap {
            score -= cap * 0.05 * (1.0 - progress);
        }
    }

    // Lookahead anticipation: when several bins fit, prefer the one whose
    // post-residual best matches the next item with a small usable gap.
    if !is_new_bin && fitting > 1.0 && next > 0.0 && post >= next {
        let gap = post - next;
        if gap > 0.0 && gap < 0.15 * cap {
            score -= cap * 0.10 * (1.0 - gap / (0.15 * cap));
        }
    }

    // COMBINED: absolute frag-zone penalty on tiny post-residuals (borrowed
    // idea, tightened) — prevents leaving dead slivers regardless of next.
    let frag = (post / cap).clamp(0.0, 1.0);
    let frag_zone = 0.10 * (1.0 - progress) + 0.04;
    if !is_new_bin && frag > 0.0 && frag < frag_zone {
        let frag_sev = 1.0 - frag / frag_zone;
        score += cap * frag_sev * (0.08 + 0.12 * open_pressure + 0.06 * mean_norm);
        if next > 0.0 && next > post {
            score += cap * 0.10 * frag_sev;
        }
    }

    // Multi-fit exact-multiple bonus for two-step chains.
    if !is_new_bin && fitting_bins_count >= 2 && next > 0.0 && post >= next {
        let alt_ratio = post / next;
        if alt_ratio.fract() < 0.15 && alt_ratio >= 2.0 {
            score -= cap * 0.04 * (1.0 - progress);
        }
    }

    score
}

