pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item fits tightly into the post residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let tightness = (post_residual - next_item_size) as f64;
        score -= 40.0 / (1.0 + tightness);
    }
    // Next item does NOT fit in post residual: penalize dead space, worse for large dead space.
    if next_item_size > 0 && next_item_size > post_residual {
        score += 15.0 + 0.2 * post_residual as f64;
    }

    // Small post residuals are good (tight packing) unless they create unusable slivers.
    if post_residual < 10 {
        score -= 10.0; // tiny leftover is effectively a full bin
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Discourage opening a new bin when existing bins fit reasonably well.
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if open bins are crowded or a great
        // 2-step match exists in this fresh bin.
        if open_bins_count > 0 {
            let avg_fill = 100.0 - mean_residual;
            score += 30.0 - 0.5 * avg_fill; // higher when bins are empty-ish
            if next_item_size > 0 && (bin_capacity as f64 - next_item_size as f64).abs() < 1.0 {
                score -= 20.0; // fresh bin perfectly fits next big item
            }
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than the mean residual.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Early in the stream, be slightly more liberal about opening bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is already the base, amplify it.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize leaving dead space that no future item (min size 1) could plausibly use well.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }

    // Lookahead coupling: if next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 12.0 * (next_item_size as f64) / (post_residual as f64);
        } else {
            // next item cannot follow here; mildly penalize
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Many open bins: prefer consolidating into existing bins, discourage new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let crowding = (open_bins_count as f64) / (1.0 + progress * 10.0);
    if bin_residual == bin_capacity {
        // New-bin candidate scoring.
        score += 10.0 + 4.0 * crowding;
        // Opening a new bin is attractive early or when open bins are nearly full on average.
        score -= 15.0 * (1.0 - mean_residual / (bin_capacity as f64));
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 8.0; // fresh bin likely useful for the upcoming large item
        }
    } else {
        // Existing bin: reward when mean residual is high (bins are loose, use them up).
        score -= 5.0 * (mean_residual / (bin_capacity as f64));
    }

    // Time horizon: late in the stream, avoid waste aggressively.
    score -= 20.0 * progress * (1.0 - (post_residual as f64) / (bin_capacity as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress.
    // Early stream: value tight fits (low post_residual) strongly.
    // Late stream: penalize dead space even more aggressively.
    let poly = pr_norm * pr_norm * (1.0 + 2.0 * progress) + 0.5 * pr_norm * (1.0 - progress);

    // Reward filling bins nearly exactly, smoothly.
    let fill_bonus = -((1.0 - pr_norm).powi(3)) * (1.0 + progress);

    // Last-chance bonus: smooth exponential reward when this is the only fitting bin.
    let last_chance = if fitting_bins_count <= 1 { -1.5 * (1.0 - progress) } else { 0.0 };

    // Lookahead coupling: if the next item fits the post-residual, reward smoothly.
    let lookahead = if next_item_size > 0 && (next_item_size as f64) <= pr {
        -0.8 * (1.0 - (next_item_size as f64 / (pr + 1.0)))
    } else {
        0.2 * (pr_norm)
    };

    // Mild penalty for scattering across many open bins vs mean residual.
    let spread = 0.1 * ((pr - mean_residual).abs() / cap);

    pr + poly * cap * 0.3 + fill_bonus * cap + last_chance + lookahead + spread
}

