pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual: divide capacity into 8 octaves.
    let octave = |r: u32| r * 8 / bin_capacity.max(1);
    let post_oct = octave(post_residual);
    let pre_oct = octave(bin_residual);

    // Reward placing into bins whose post-residual falls in "usable" octaves
    // (residuals that still admit mid-size items: octaves 2..5).
