        0 => score -= 30.0,               // near-perfect fill
        1 => score -= 22.0,
        2 => score -= 14.0,
        3 => score -= 8.0,
        4 => score -= 2.0,
        5 => {}                            // neutral
        6 => score += 8.0,                 // wasteful large remainder
        _ => score += 16.0,
    }

    // Penalize crossing octave boundaries with big jumps (creates dead zones).
    if post_oct < pre_oct && (pre_oct - post_oct) >= 3 {
        score += 10.0;
    }

    // Modulo coupling: does next item fit the post-residual exactly-ish?
