            score -= 25.0;
        } else {
            score -= 10.0 * (1.0 - slack as f64 / post_residual.max(1) as f64);
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Post-residual too small for lookahead: dead space penalty scaled by size.
        score += 6.0 + post_residual as f64 / bin_capacity as f64 * 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: prefer it only late in stream with many open bins,
    // or when current fit is terrible (large post_residual).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let bad_fit = post_residual as f64 / bin_capacity as f64;
        score += 35.0 - 25.0 * progress - 30.0 * bad_fit - (open_bins_count as f64).min(10.0);
    }

    // Mean-residual pressure: if open bins are generally full, reward tight fits more.
    score -= (mean_residual / bin_capacity.max(1) as f64) * (bin_capacity - post_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small post-residuals are nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // dead space: gap too small for any item
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit: reward strongly
    }

    // Exact-fit lookahead: if next item fits the post residual, reward.
    if next_item_size > 0 && post_residual > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 10.0 {
            score -= 35.0; // chain fit: near-perfect follow-up
        } else {
            score -= 15.0;
        }
    }

    // Last-chance bin pressure: if this is the only bin that fits, avoid
    // opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual < bin_capacity as f64 - item_size as f64 {
        score -= 30.0;
    }

    // Open-bin pressure: discourage spreading across many bins when
    // mean residual is already high (bins are underfilled).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64 / (1.0 + mean_residual / 10.0)) * (1.0 - 0.5 * progress);
    score += 0.05 * pressure;

    // Prefer bins tighter than the average residual (best-fit coupling).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.1 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits exactly in post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0; // chain of perfect fits
        } else if next_item_size <= post_residual {
            let rem2 = post_residual - next_item_size;
            // reward tight two-item packing
            score -= 200.0 * (rem2 as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize dead space slightly
            score += 20.0;
        }
    }

    // Compare post_residual against mean residual: prefer bins becoming "average tightness"
    let diff = post_residual as f64 - mean_residual;
    score += 0.5 * diff;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize mildly unless existing bins are terrible
    if bin_residual == bin_capacity {
        score += 250.0;
        // allow new bin early in stream or when few bins open
        if open_bins_count < 3 {
            score -= 100.0;
        }
    }

    // Late in stream: be more conservative, avoid wasting space
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 30.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space: post_residual too small to hold typical future items.
    if post_residual > 0 {
        let min_item = 1.0f64;
        let dead = (post_residual as f64).max(min_item);
        if post_residual < 10 {
            score += 25.0 * (10.0 - dead) / 10.0;
        }
    }

    // Last-chance bin: strongly reward using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current bin fit is poor.
    if bin_residual == bin_capacity {
        let fit_quality = (post_residual as f64) / bin_capacity as f64;
        // Opening a new bin is only attractive if the item fits perfectly in an empty bin
        // AND existing bins would leave large dead space.
        score += 15.0;
        if item_size >= 90 {
            score -= 20.0; // huge items fit well in fresh bins
        }
        let _ = fit_quality;
    }

    // Lookahead: if the next item could fit into the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as i64) >= (next_item_size as i64) {
        score -= 12.0;
    } else if next_item_size > 0 {
        // Penalize placements that leave a residual the next item almost fits into.
        let gap = next_item_size as f64 - post_residual as f64;
        if gap > 0.0 && gap < 15.0 {
