pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals that are multiples of common
    // item sizes (or leave useful fractions of capacity) are more valuable.
    let pr = post_residual;
    if pr > 0 {
        // Modulo harmony: post_residual divisible by small harmonics is reusable.
        let mut harmony_bonus = 0.0;
        for &h in &[10u32, 20, 25, 50] {
            if pr % h == 0 {
                harmony_bonus += 4.0;
            }
        }
        score -= harmony_bonus;

        // Dead-space penalty: residuals in awkward bands (e.g. 1..10 or 51..59)
        // are hard to fill; push such bins away.
        if pr < 10 {
            score += 25.0;
        } else if pr > 50 && pr < 60 {
            score += 8.0;
        }

        // Integer-division threshold: pr/10 class reward for large usable space.
        let class = pr / 10;
        score -= (class as f64) * 0.5;
    } else {
        // Perfect fit: strongly favored.
        score -= 100.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // this placement is excellent.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score -= 10.0; // next item leaves near-perfect state
        } else if next_item_size > post_residual && post_residual > 0 {
            score += 5.0; // next item won't fit here anyway
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Mean-residual anchoring: prefer bins whose resulting residual is close to
    // the mean (keeps fleet balanced), penalize divergence.
    score += ((post_residual as f64) - mean_residual).abs() * 0.15;

    // New-bin candidate handling: an empty bin has high post_residual; make it
    // attractive only when current bins would leave small dead space anyway.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Early on, opening fresh bins is cheap; later, prefer filling.
        score += 6.0 + 20.0 * (1.0 - progress);
        if item_size >= 50 {
            score -= 5.0; // big items pair well with fresh bins
        }
    }

    // Fraction-of-capacity harmony on the item itself.
    let frac = item_size as f64 / bin_capacity as f64;
    score -= (frac * 2.0 - 1.0).abs() * 3.0;

    // Slight preference for fewer open bins (bin consolidation).
    score += (open_bins_count as f64) * 0.02;

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    let cap = bin_capacity.max(1) as f64;
    let post = post_residual as f64;
    let next = next_item_size as f64;
    let open = open_bins_count as f64;
    let fitting = fitting_bins_count as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let mean_norm = (mean_residual / cap).clamp(0.0, 1.0);
    let item_norm = (item_size as f64 / cap).clamp(0.0, 1.0);
    let open_pressure = open / (open + 5.0);
    let is_new_bin = bin_residual == bin_capacity;

    // Slightly damp raw residual so post-placement tightness dominates.
    let mut score = post * 0.95 + item_norm * 0.05;

    // Reward exact closure, scaled by how crowded the bin set is.
    if post_residual == 0 {
        score -= cap * (0.24 + 0.30 * open_pressure + 0.10 * progress);
    }

    // Dead-space avoidance with convex severity for tiny stranded slivers.
    let dead_limit = next.max(0.10 * cap);
    if post > 0.0 && post < dead_limit {
        let missing = dead_limit - post;
        let severity = 1.0 + (1.0 - post / dead_limit).powi(2);
        let dead_weight = (2.4 + 1.3 * open_pressure + 0.6 * progress + 0.5 * mean_norm) * severity;
        score += missing * dead_weight;
    }

    // Breaking the immediate lookahead chain is a serious fragmentation cost.
    if next > 0.0 && post > 0.0 && post < next {
        score += cap * (0.45 + 0.35 * (1.0 - post / next));
    }

    // Reward placements that leave just enough room for the next item,
    // with a tighter quadratic curve favoring snug fits.
    if next > 0.0 && post >= next {
        let slack = ((post - next) / cap).clamp(0.0, 1.0);
        let tightness = 1.0 - slack * slack;
        score -= cap * (0.18 + 0.07 * progress) * tightness;

        // Exact-multiple chain potential.
        let ratio = post / next;
        let mult_err = (ratio - ratio.round()).abs();
        if mult_err < 0.02 {
            score -= cap * 0.06 * (1.0 - 0.5 * progress);
        }
    }

    // Two-step lookahead: stranded tiny gaps late in the stream.
    if post > 0.0 && next > 0.0 && post < next && post < 0.06 * cap {
        score += cap * (0.15 + 0.20 * progress);
    }

    // Fragmentation-anticipation: awkward band just above the next item.
    if !is_new_bin && post > next && next > 0.0 {
        let awkward = (next + mean_residual.min(cap)).min(cap);
        if post < awkward {
            let depth = 1.0 - (awkward - post) / awkward.max(1.0);
            score += cap * 0.08 * depth * (0.5 + 0.5 * progress);
        }
    }

    if is_new_bin {
        let fit_pressure = fitting.min(4.0);
        let mut new_penalty = cap
            * (0.18 + 0.45 * open_pressure + 0.10 * mean_norm + 0.05 * fit_pressure)
            * (1.10 - 0.25 * item_norm);

        // A new bin that cannot absorb the next item is especially wasteful.
        if next > 0.0 && post < next {
            new_penalty += cap * (0.70 + 0.25 * (1.0 - post / next));
        }

        // Late in the stream, opening bins is nearly always wasteful.
        new_penalty += cap * 0.10 * progress;

        // Relax penalty when current bins are already highly fragmented.
        new_penalty *= 1.0 - 0.15 * (1.0 - mean_norm) * open_pressure;

        // Opening is attractive when the item nearly fills a fresh bin.
        if item_norm > 0.90 {
            new_penalty -= cap * 0.35 * (item_norm - 0.90) / 0.10;
        }

        // No lookahead info: opening a fresh bin is mildly more acceptable early.
        if next == 0.0 {
            new_penalty -= cap * 0.05 * (1.0 - progress);
        }

        score += new_penalty;
    } else if fitting_bins_count == 1 {
        // Strongly prefer the last open bin that can still take the item.
        score -= cap * (0.20 + 0.30 * open_pressure + 0.05 * progress);
    } else if next > 0.0 {
        // Chain-fit preference: residuals close to a multiple of next item.
        let ratio = post / next;
        let chain_fit = (ratio.round() - ratio).abs();
        let chain_weight = 0.06 + 0.02 * fitting.min(5.0);
        score += chain_fit * next * chain_weight;
    }

    // Prefer bins whose residual stays usable for the average remaining item.
    if !is_new_bin && post > 0.0 && mean_residual > 0.0 {
        let usable = (post / mean_residual).clamp(0.0, 4.0);
        score += (2.0 - usable).abs() * 0.05 * cap * (1.0 - progress);
    }

    // Compaction reward: prefer the fullest bins after placement.
    if !is_new_bin && post > 0.0 {
        let fill_after = 1.0 - post / cap;
        score -= fill_after * cap * 0.05 * (1.0 - fitting.min(3.0) / 3.0);
    }

    // Frag-zone penalty: small residual fractions become dead space.
    let frag = if post > 0.0 { (post / cap).clamp(0.0, 1.0) } else { 0.0 };
    let frag_zone = 0.10 * (1.0 - progress) + 0.04;
    if frag > 0.0 && frag < frag_zone {
        let frag_sev = 1.0 - frag / frag_zone;
        score += cap * frag_sev * (0.08 + 0.12 * open_pressure + 0.06 * mean_norm);
        if next > 0.0 && next > post {
            score += cap * 0.10 * frag_sev;
        }
    }

    // Multi-fit chain bonus: residuals that are clean multiples (>=2x) of next.
    if !is_new_bin && fitting_bins_count >= 2 && next > 0.0 && post >= next {
        let alt_ratio = post / next;
        if alt_ratio.fract() < 0.15 && alt_ratio >= 2.0 {
            score -= cap * 0.04 * (1.0 - progress);
        }
    }

    // Snug double-fit reward: residual fits exactly two of the next item.
    if !is_new_bin && post > next && next > 0.0 && post >= next && post < 2.0 * next {
        score -= cap * 0.03 * (1.0 - 0.5 * progress) * (1.0 - (post / next - 1.0));
    }

    score
}

