    let mut score = post_residual as f64;

    // Penalize unusable dead space: small post-residuals that no future item can use.
    // Items are >= 1; treat post_residual below a "usable threshold" as wasted.
    let dead_threshold = 12u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += (dead_threshold - post_residual) as f64 * 3.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into new bins;
    // favor filling existing ones (a new bin has bin_residual == bin_capacity and
    // gets the full pressure penalty).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 10.0 + 15.0 * progress + (open_bins_count as f64) * 0.5;
    } else {
        score -= (open_bins_count as f64) * 0.2;
    }

    // Lookahead: if next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 20.0;
        } else if slack < dead_threshold {
            score -= 8.0;
        }
    }

    // Mild preference for bins tighter than average residual (best-fit flavor).
    score += (bin_residual as f64 - mean_residual) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact fit (no dead space)
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if the next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // next item fits: mild reward proportional to how snugly
            score -= 50.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item does NOT fit: penalize leftover that is too small for next item
            score += 30.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    } else {
