        score += (dead_threshold - post) * 2.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item, prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, big reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as u32) >= next_item_size {
            let next_tightness = 1.0 - (post - nxt) / cap;
            score -= 15.0 * next_tightness * next_tightness;
        } else if post_residual as u32 > 0 {
            // Next item cannot fit here; mildly penalize leaving awkward gaps.
            score += 5.0;
        }
    }

    // Global state coupling: when many bins are open with high mean residual,
    // discourage opening new bins (consolidate); when open bins are nearly full,
    // opening a new bin is natural.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let _ = progress;
    if bin_residual as u32 == bin_capacity as u32 {
        // New-bin candidate: penalize when existing bins have lots of room,
        // especially with many open bins (avoid fragmentation).
        let room = mean_residual / cap;
        score += 40.0 * room * (1.0 + (open_bins_count as f64).ln().max(0.0));
        // But if no open bin fits well (best post would be huge), the tight-fit
        // reward above on real bins fades; new-bin penalty shrinks late in stream.
        score -= 10.0 * (1.0 - room);
    }

    // Slight preference for filling fuller bins among ties.
    score += 0.1 * (cap - residual) / cap;

    score
}

