    }

    // Mild penalty for fragmentation when many bins are open
    score += 0.5 * (open_bins_count as f64).ln() * x;

    // New-bin candidate: neutral-ish baseline, penalize slightly so it's
    // chosen only when fits are poor; relax early in the stream
    if bin_residual == bin_capacity {
        score += 5.0 - 4.0 * (1.0 - progress) * (1.0 - x);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but heavily penalize
    // unusable dead space via harmonic classes of post_residual.
    if post_residual > 0 {
        // Harmonic class: items 1..100, capacity 100. Residuals in [1,9]
        // are near-dead space (few future items fit); [10,50] recoverable.
        if post_residual < 10 {
            score += 60.0 * (10.0 - post_residual as f64);
        } else if post_residual <= 50 {
            // Reward residuals that are good harmonic targets: multiples of 10
            // and small values are easier to fill.
            let r = post_residual as f64;
            let mult10 = if post_residual % 10 == 0 { -8.0 } else { 0.0 };
            score += 0.35 * r + mult10;
        }
        // Residuals > 50 are roomy; slight bonus so big bins absorb items.
        else {
            score -= 4.0;
        }
    } else {
        // Perfect fill: strong reward.
        score -= 40.0;
    }

    // Perfect-fill harmonic classes: item sizes dividing capacity evenly.
    if item_size > 0 && bin_capacity % item_size == 0 {
        score -= 6.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly favor this bin (chained perfect fill).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            // Next item fits: mild reward scaled by tightness of next fit.
            let nr = post_residual - next_item_size;
            score -= 6.0 * (1.0 - nr as f64 / 100.0);
        } else {
            // Next item won't fit here: penalize if it's a large next item
            // that we might want room for.
            score += 0.05 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance logic: if this is the only fitting bin, avoid forcing
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: an empty bin has post_residual == capacity.
    // Make opening a new bin attractive only when open bins are crowded
    // and mean residual is low (stream is packing well).
    if bin_residual == bin_capacity {
        // Base new-bin score: moderate, so it only wins when open bins
        // have bad (small or fragmented) residuals.
        score = 55.0
            + 0.25 * mean_residual
            - 3.0 * open_bins_count as f64
            - 10.0 * (step_index as f64 / total_items.max(1) as f64);
        // If the current fit is bad (large item into residual leaving tiny gap),
        // new bin becomes competitive.
        if post_residual > 0 && post_residual < 10 {
            score -= 30.0;
        }
    }

    // Early stream: be slightly conservative about fragmenting bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.3 && post_residual > 0 && post_residual < 15 {
        score += 10.0 * (1.0 - progress / 0.3);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Post-residual that cannot fit even the smallest conceivable item (1..100 range)
    // is pure waste; scale penalty by how close it is to the dead zone.
    if post_residual > 0 && post_residual < 20 {
        score += (20 - post_residual) as f64 * 2.5;
    }

    // Reward tight fits (low post residual relative to bin).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 25.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones;
    // the empty-bin candidate gets penalized proportionally.
    if bin_residual == bin_capacity {
        score += 40.0 + open_bins_count as f64 * 8.0;
        // But if this is the last fitting bin, allow new bin to compete.
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        if gap < 5.0 {
            score -= 30.0;
        } else {
            score -= 10.0 * (1.0 - gap / bin_capacity as f64);
        }
    }
    // Penalize if next item would NOT fit here (dead end for lookahead).
    if next_item_size > post_residual && post_residual > 0 {
        score += 8.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins first),
    // keeping loose bins available for awkward future items.
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Late-stream consolidation: as the stream progresses, be more aggressive
    // about filling existing bins rather than opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= progress * 10.0;
    } else {
        score += progress * 15.0;
    }

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    let cap = bin_capacity.max(1) as f64;
    let post = post_residual as f64;
    let next = next_item_size as f64;
    let open = open_bins_count as f64;
    let fitting = fitting_bins_count as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let mean_norm = (mean_residual / cap).clamp(0.0, 1.0);
    let item_norm = (item_size as f64 / cap).clamp(0.0, 1.0);
    let open_pressure = open / (open + 5.0);
    let is_new_bin = bin_residual == bin_capacity;

    // Base: slight blend with item size (borrowed from best) to break ties
    // toward fuller placements.
    let mut score = post * 0.95 + item_norm * 0.05;

    // Reward exact closure, scaled by how crowded the bin set is.
    if post_residual == 0 {
        score -= cap * (0.24 + 0.30 * open_pressure + 0.10 * progress);
    }

    // Dead-space avoidance with convex severity for tiny stranded slivers.
    let dead_limit = next.max(0.10 * cap);
    if post > 0.0 && post < dead_limit {
        let missing = dead_limit - post;
        let severity = 1.0 + (1.0 - post / dead_limit).powi(2);
        let dead_weight = (2.4 + 1.3 * open_pressure + 0.6 * progress + 0.5 * mean_norm) * severity;
        score += missing * dead_weight;
    }

    // Breaking the immediate lookahead chain is a serious fragmentation cost.
    if next > 0.0 && post > 0.0 && post < next {
        score += cap * (0.45 + 0.35 * (1.0 - post / next));
    }

    // Reward placements that leave just enough room for the next item,
    // with a tighter quadratic curve favoring snug fits.
    if next > 0.0 && post >= next {
        let slack = ((post - next) / cap).clamp(0.0, 1.0);
        let tightness = 1.0 - slack * slack;
        score -= cap * (0.18 + 0.07 * progress) * tightness;

        // Exact-multiple chain potential: post_residual a clean multiple of
        // next_item_size enables a sequence of future perfect fits.
        let ratio = post / next;
        let mult_err = (ratio - ratio.round()).abs();
        if mult_err < 0.02 {
            score -= cap * 0.06 * (1.0 - 0.5 * progress);
        }
    }

    // Two-step lookahead: stranded tiny gaps late in the stream.
    if post > 0.0 && next > 0.0 && post < next && post < 0.06 * cap {
        score += cap * (0.15 + 0.20 * progress);
    }

    // Fragmentation zone: penalize residuals in a narrow low band, stronger
    // early in the stream (idea from the best heuristic).
    let frag = if post > 0.0 { (post / cap).clamp(0.0, 1.0) } else { 0.0 };
    let frag_zone = 0.10 * (1.0 - progress) + 0.04;
    if !is_new_bin && frag > 0.0 && frag < frag_zone {
        let frag_sev = 1.0 - frag / frag_zone;
        score += cap * frag_sev * (0.08 + 0.12 * open_pressure + 0.06 * mean_norm);
        if next > 0.0 && next > post {
            score += cap * 0.10 * frag_sev;
        }
    }

    // Multi-fit chain bonus: residuals that can host the next item at least
    // twice with a clean split get a compaction reward.
    if !is_new_bin && fitting_bins_count >= 2 && next > 0.0 && post >= next {
        let alt_ratio = post / next;
        if alt_ratio.fract() < 0.15 && alt_ratio >= 2.0 {
            score -= cap * 0.04 * (1.0 - progress);
        }
    }

    // Fragmentation-anticipation: residuals in the awkward band just above
    // the next item but below next + mean item likely become dead space.
    if !is_new_bin && post > next && next > 0.0 {
        let awkward = (next + mean_residual.min(cap)).min(cap);
        if post < awkward {
            let depth = 1.0 - (awkward - post) / awkward.max(1.0);
            score += cap * 0.08 * depth * (0.5 + 0.5 * progress);
        }
    }

    // Snug double-fit reward: residual fits next item exactly once more-ish.
    if !is_new_bin && post > next && next > 0.0 && post < 2.0 * next {
        score -= cap * 0.03 * (1.0 - 0.5 * progress) * (1.0 - (post / next - 1.0));
    }

    if is_new_bin {
        let fit_pressure = fitting.min(4.0);
        let mut new_penalty = cap
            * (0.18 + 0.45 * open_pressure + 0.10 * mean_norm + 0.05 * fit_pressure)
            * (1.10 - 0.25 * item_norm);

        // A new bin that cannot absorb the next item is especially wasteful.
        if next > 0.0 && post < next {
            new_penalty += cap * (0.70 + 0.25 * (1.0 - post / next));
        }

        // Late in the stream, opening bins is nearly always wasteful.
        new_penalty += cap * 0.10 * progress;

        // Relax penalty when current bins are already highly fragmented.
        new_penalty *= 1.0 - 0.15 * (1.0 - mean_norm) * open_pressure;

        // Opening is attractive when the item nearly fills a fresh bin.
        if item_norm > 0.90 {
            new_penalty -= cap * 0.35 * (item_norm - 0.90) / 0.10;
        }

        // End-of-stream: last items go to fresh bins more freely.
        if next == 0.0 {
            new_penalty -= cap * 0.05 * (1.0 - progress);
        }

        score += new_penalty;
    } else if fitting_bins_count == 1 {
        // Strongly prefer the last open bin that can still take the item.
        score -= cap * (0.20 + 0.30 * open_pressure + 0.05 * progress);
    } else if next > 0.0 {
        // Chain-fit preference: reward residuals close to a multiple of the
        // next item size, scaled by how many competing bins exist.
        let ratio = post / next;
        let chain_fit = (ratio.round() - ratio).abs();
        let chain_weight = 0.06 + 0.02 * fitting.min(5.0);
        score += chain_fit * next * chain_weight;
    }

    // Prefer bins whose residual stays usable for the average remaining item.
    if !is_new_bin && post > 0.0 && mean_residual > 0.0 {
        let usable = (post / mean_residual).clamp(0.0, 4.0);
        score += (2.0 - usable).abs() * 0.05 * cap * (1.0 - progress);
    }

    // Compaction reward: prefer the fullest bins after placement, strongest
    // when few alternative bins compete.
    if !is_new_bin && post > 0.0 {
        let fill_after = 1.0 - post / cap;
        score -= fill_after * cap * 0.05 * (1.0 - fitting.min(3.0) / 3.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but dead space that
    // cannot fit the smallest plausible item is very bad.
    if post_residual > 0 && post_residual < 10 {
        score -= 15.0; // near-perfect fill
    } else if post_residual >= 10 && post_residual < 40 {
        score -= 5.0;
    } else if post_residual >= 60 {
        score += 10.0; // large dead space penalty
    }

    // 2-step lookahead: perfect chaining reward if next item exactly fills
    // the post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0; // perfect 2-step match
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // next item won't fit here: penalize proportionally to the gap
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Compare residual against mean residual of open bins: prefer bins that
    // are already more filled (lower residual) to consolidate load.
    score += (bin_residual as f64 - mean_residual) * 0.25;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Penalize opening a new bin when good fitting bins exist, but allow it
    // when current bins would leave large unusable gaps.
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline score is bin_capacity - item_size.
        // Acceptable only if it beats wasting space elsewhere.
        score += open_bins_count as f64 * 0.5;
        if fitting_bins_count > 0 && post_residual as f64 > mean_residual {
            score += 8.0;
        }
    }

    // Slight preference early in stream to keep bins open (flexibility),
    // stronger consolidation later.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 2.0;

    score
}

pub fn score_bin(
