pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual), amplified early when space is precious.
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += 25.0 * tightness * (1.0 - t);

    // Penalize leaving dead space that no plausible item (>=10) can use.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0;
    } else if post_residual > 0 && post_residual < 20 {
        score += 12.0 * (20.0 - post_residual as f64) / 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    } else if fitting_bins_count <= 3 && bin_residual < bin_capacity {
        score -= 6.0;
    }

    // Lookahead: if next item fits the post residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // Penalize placements that strand the next item.
            score += 4.0 * (next_item_size as f64 - post_residual as f64).min(30.0) / 30.0;
        }
    }

    // When many bins are open, prefer compacting into fuller bins.
    score += 0.5 * (open_bins_count as f64).ln() * (bin_residual as f64 / bin_capacity as f64);

    // Slight preference toward bins below average fullness when residuals are large.
    if bin_residual as f64 > mean_residual && bin_residual < bin_capacity {
        score += 3.0;
    }

    // New-bin candidate: only attractive when the item is huge or fits are scarce.
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let huge = (item_size as f64 / bin_capacity as f64) > 0.7;
        if scarcity > 0.5 || huge {
            score -= 20.0;
        } else {
            score += 15.0 + 10.0 * (1.0 - t);
        }
    }

    // Late stream: prioritize closing bins out, penalize spreading.
    score += t * 5.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
