            score += 15.0 + diff * 0.3;
        }
    }

    // Penalize very small post_residual (unusable dead space), unless it perfectly matched
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        score += (10.0 - pr) * 2.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Reward filling bins tighter than the current mean residual
    score -= 0.5 * (mean_residual - pr);

    // New-bin candidate: make it attractive only when no open bin fits well.
    // Base new-bin score near capacity residual; add mild penalty so existing bins win on good fits.
    if bin_residual == bin_capacity {
        score += 20.0;
        // If the next item is large relative to a fresh bin's value, opening fresh is fine
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Late in the stream: consolidate more aggressively into existing bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual != bin_capacity {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that few future items could use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual >= 10 && post_residual <= 20 {
        score -= 5.0; // still usable for small items
    }

    // Lookahead: reward if the next item fits exactly or well into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect chaining
        } else if next_item_size < post_residual {
            let next_fit = next_item_size as f64 / post_residual as f64;
            score -= 15.0 * next_fit;
        } else {
            score += 8.0; // next item won't fit here; keep residual flexible
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Time horizon: early in the stream, be more selective (prefer good fits);
    // late in the stream, close bins out aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (bin_capacity - bin_residual) as f64 / bin_capacity as f64;

    // Global state coupling: many open bins with high mean residual -> prefer filling existing bins.
    if open_bins_count > 4 && mean_residual > item_size as f64 {
        score -= 6.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is huge and fit elsewhere is bad.
    if bin_residual == bin_capacity {
        score += 45.0;
        if item_size >= 70 && fitting_bins_count <= 2 {
            score -= 50.0; // big item: starting fresh can be better
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 20.0; // pair the next item into the new bin
        }
    }

    score
}

