pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, prefer filling bins tightly (minimize post_residual),
    // later, tolerate residual since new bins amortize anyway.
    let pn = pr / cap; // normalized post residual in [0,1]
    let poly = pn * pn * (1.0 - progress) + pn * progress * 0.5;
    score += poly * cap * 0.8;

    // Reward near-perfect fits with a smooth quadratic bonus.
    let fit_bonus = (1.0 - pn) * (1.0 - pn);
    score -= fit_bonus * item_size as f64 * 0.6;

    // Penalize dead space that can't fit the lookahead item (smooth interaction).
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0);
        score += (gap / cap) * (gap / cap) * cap * (0.5 + progress);
    }

    // Last-chance bin gets a smooth urgency discount.
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - progress * 0.5);
    }

    // Slight preference for bins with residual close to mean (smoothness).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * dev * 5.0;

    // Discourage opening new bins when many bins already fit the item.
    score += (fitting_bins_count as f64).ln().max(0.0) * -1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "clean"
    // residue classes (multiples of 10) remain reusable by common item sizes.
    let pr = post_residual as i64;
    if pr > 0 {
        let class = pr % 10;
        // Penalize "dirty" leftovers (odd residues) that few item sizes can use.
        score += match class {
            0 => -6.0,
            2 | 5 => 0.0,
            _ => 4.0 + (class as f64) * 0.5,
        };
    } else {
        // Perfect closure of the bin is excellent.
        score -= 15.0;
    }

    // Integer-division thresholds: post_residual bucketed by usability.
    if pr > 0 && pr < 10 {
        // Dead space: too small for any item (min size 1, but typical sizes larger).
        score += 12.0;
    } else if pr >= 10 && pr <= 25 {
        // Sweet spot: leftover likely usable by a small next item.
        score -= 5.0;
    }

    // Lookahead coupling: does post_residual fit next_item_size exactly / well?
    if next_item_size > 0 {
        let nxt = next_item_size as i64;
        if pr == nxt {
            score -= 14.0; // perfect chaining
        } else if pr >= nxt {
            let slack = (pr - nxt) as f64;
            score -= 8.0 * (1.0 - slack / 100.0).max(0.0);
        } else {
            // Next item cannot use this bin's leftover; penalize proportionally.
            score += 3.0 * (nxt - pr) as f64 / 10.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current fit is bad
    // and there are many open bins already.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / (total_items.max(1) as f64);
        score += 25.0 - 10.0 * pressure;
        if next_item_size > 0 && next_item_size >= item_size {
            score += 5.0; // pairing lookahead favors consolidating first
        }
    }

    // Mean residual coupling: placing into a bin far below mean residual
    // balances the pool of open bins.
    let dev = mean_residual - post_residual as f64;
    score += 0.15 * dev.abs().signum() * dev;

    // Late-stream consolidation: fewer bins preferred as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftover gaps are wasted capacity.
    if post_residual > 0 {
        if post_residual <= 10 {
            // Gap too small for the minimum item size (1..100 interface, min 10 in classic case):
            // pure dead space -> heavy penalty.
            score += 60.0;
        } else if post_residual <= 25 {
            // Small gap: only fitable by very small items; penalize proportionally.
            score += (25.0 - post_residual as f64) * 2.5;
        } else if post_residual <= 40 {
            // Medium gap: mild penalty, still reasonably usable.
            score += (40.0 - post_residual as f64) * 0.8;
        }
        // Large residuals are naturally favored by the base score already.
    } else {
        // Perfect fit: strong reward.
        score -= 50.0;
    }

    // Reward exact/near-exact fits relative to bin size.
    let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 20.0;

    // Open-bins pressure: when many bins are open, prefer consolidation into
    // existing bins; penalize the brand-new-bin candidate (residual == capacity).
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as open bins accumulate.
        score += 15.0 + 3.0 * open_bins_count as f64;
    } else {
        // Reusing an existing bin relieves pressure.
        score -= 2.0 + open_bins_count.min(20) as f64 * 0.5;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (avoiding bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward
    // this placement for creating a perfect future slot.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size <= post_residual && post_residual - next_item_size <= 10 {
        // Next item leaves near-dead space: mild penalty.
        score += 5.0;
    }

    // Early in the stream, be slightly more willing to open bins (build a
    // diverse residual portfolio); late in the stream, consolidate hard.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    } else {
        score += 5.0 * progress;
    }

    // Slight nudge toward bins with below-average residual (tighter bins),
    // keeping loose bins available for large future items.
    score += (mean_residual - bin_residual as f64).clamp(-30.0, 30.0) * 0.15;

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    let cap = bin_capacity.max(1) as f64;
    let post = post_residual as f64;
    let next = next_item_size as f64;
    let open = open_bins_count as f64;
    let fitting = fitting_bins_count as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let mean_norm = (mean_residual / cap).clamp(0.0, 1.0);
    let item_norm = (item_size as f64 / cap).clamp(0.0, 1.0);
    let open_pressure = open / (open + 5.0);
    let is_new_bin = bin_residual == bin_capacity;

    let mut score = post * 0.95 + item_norm * 0.05;

    // Reward exact closure, scaled by how crowded the bin set is.
    if post_residual == 0 {
        score -= cap * (0.24 + 0.30 * open_pressure + 0.10 * progress);
    }

    // Dead-space avoidance with convex severity for tiny stranded slivers.
    let dead_limit = next.max(0.10 * cap);
    if post > 0.0 && post < dead_limit {
        let missing = dead_limit - post;
        let severity = 1.0 + (1.0 - post / dead_limit).powi(2);
        let dead_weight = (2.4 + 1.3 * open_pressure + 0.6 * progress + 0.5 * mean_norm) * severity;
        score += missing * dead_weight;
    }

    // Breaking the immediate lookahead chain is a serious fragmentation cost.
    if next > 0.0 && post > 0.0 && post < next {
        score += cap * (0.45 + 0.35 * (1.0 - post / next));
    }

    // Reward placements that leave just enough room for the next item,
    // with a tighter quadratic curve favoring snug fits.
    if next > 0.0 && post >= next {
        let slack = ((post - next) / cap).clamp(0.0, 1.0);
        let tightness = 1.0 - slack * slack;
        score -= cap * (0.18 + 0.07 * progress) * tightness;

        // Exact-multiple chain potential: post_residual a clean multiple of
        // next_item_size enables a sequence of future perfect fits.
        let ratio = post / next;
        let mult_err = (ratio - ratio.round()).abs();
        if mult_err < 0.02 {
            score -= cap * 0.06 * (1.0 - 0.5 * progress);
        }
        // Multi-step chain: residual >= 2*next with near-integer ratio
        // promises several consecutive perfect fits; reward more strongly
        // when many bins compete for the item.
        if ratio >= 2.0 && ratio.fract() < 0.15 && fitting >= 2 {
            score -= cap * 0.05 * (1.0 - progress) * (1.0 - fitting.min(5.0) / 5.0);
        }
        // Snug second-fit bonus: residual just above next, still usable.
        if post < 2.0 * next {
            score -= cap * 0.03 * (1.0 - 0.5 * progress) * (1.0 - (ratio - 1.0));
        }
    }

    // Two-step lookahead: stranded tiny gaps late in the stream.
    if post > 0.0 && next > 0.0 && post < next && post < 0.06 * cap {
        score += cap * (0.15 + 0.20 * progress);
    }

    // Fragmentation-anticipation: residuals in the awkward band just above
    // the next item but below next + mean item likely become dead space.
    if !is_new_bin && post > next && next > 0.0 {
        let awkward = (next + mean_residual.min(cap)).min(cap);
        if post < awkward {
            let depth = 1.0 - (awkward - post) / awkward.max(1.0);
            score += cap * 0.08 * depth * (0.5 + 0.5 * progress);
        }
    }

    if is_new_bin {
        let fit_pressure = fitting.min(4.0);
        let mut new_penalty = cap
            * (0.18 + 0.45 * open_pressure + 0.10 * mean_norm + 0.05 * fit_pressure)
            * (1.10 - 0.25 * item_norm);

        // A new bin that cannot absorb the next item is especially wasteful.
        if next > 0.0 && post < next {
            new_penalty += cap * (0.70 + 0.25 * (1.0 - post / next));
        }

        // Late in the stream, opening bins is nearly always wasteful.
        new_penalty += cap * 0.10 * progress;

        // Relax penalty when current bins are already highly fragmented.
        new_penalty *= 1.0 - 0.15 * (1.0 - mean_norm) * open_pressure;

        // Opening is attractive when the item nearly fills a fresh bin.
        if item_norm > 0.90 {
            new_penalty -= cap * 0.35 * (item_norm - 0.90) / 0.10;
        }

        score += new_penalty;
    } else if fitting_bins_count == 1 {
        // Strongly prefer the last open bin that can still take the item.
        score -= cap * (0.20 + 0.30 * open_pressure + 0.05 * progress);
    } else if next > 0.0 {
        // Chain-fit preference: reward residuals close to a multiple of the
        // next item size, scaled by how many competing bins exist.
        let ratio = post / next;
        let chain_fit = (ratio.round() - ratio).abs();
        let chain_weight = 0.06 + 0.02 * fitting.min(5.0);
        score += chain_fit * next * chain_weight;
    }

    // Prefer bins whose residual stays usable for the average remaining item.
    if !is_new_bin && post > 0.0 && mean_residual > 0.0 {
        let usable = (post / mean_residual).clamp(0.0, 4.0);
        score += (2.0 - usable).abs() * 0.05 * cap * (1.0 - progress);
    }

    // Compaction reward: prefer the fullest bins after placement, strongest
    // when few alternative bins compete.
    if !is_new_bin && post > 0.0 {
        let fill_after = 1.0 - post / cap;
        score -= fill_after * cap * 0.05 * (1.0 - fitting.min(3.0) / 3.0);
    }

    // Low-residual fragmentation zone penalty: residuals too small to be
    // useful for typical items become dead weight; strongest early.
    let frag = if post > 0.0 { (post / cap).clamp(0.0, 1.0) } else { 0.0 };
    let frag_zone = 0.10 * (1.0 - progress) + 0.04;
    if frag > 0.0 && frag < frag_zone {
        let frag_sev = 1.0 - frag / frag_zone;
        score += cap * frag_sev * (0.08 + 0.12 * open_pressure + 0.06 * mean_norm);
        if next > 0.0 && next > post {
            score += cap * 0.10 * frag_sev;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Aggressive 2-step lookahead: if the next item fits exactly into post_residual,
    // this placement chains perfectly — reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            let slack = post_residual - next_item_size;
            if slack <= 5 {
                score -= 120.0;
            } else if slack <= 15 {
                score -= 40.0;
            } else {
                // Penalize leaving a gap the next item cannot fill well.
                score += slack as f64 * 0.5;
            }
        } else {
            // Next item doesn't fit here; dead space relative to next item.
            let gap = next_item_size - post_residual;
            if gap <= 5 {
                score += 10.0;
            } else {
                score += gap as f64 * 0.8;
            }
        }
    }

    // Compare against mean residual: bins below mean residual are more "loaded";
    // prefer filling already-low-residual bins to consolidate.
    score += (bin_residual as f64 - mean_residual) * 0.6;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current
    // residuals are all poor fits (large post_residual waste).
    if bin_residual == bin_capacity {
        score += 30.0;
        // If lookahead chains well in a fresh bin (e.g., item + next ≈ capacity), allow it.
        if next_item_size > 0 && (item_size + next_item_size) as f64 >= bin_capacity as f64 * 0.95 {
            score -= 90.0;
        }
        // Late in the stream, opening fresh bins is cheaper than fragmenting.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if post_residual as f64 > mean_residual + 20.0 {
            score -= 40.0 * progress;
        }
    }

    // Mild preference to spread across many open bins when they are plentiful.
    score += open_bins_count as f64 * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 6.0 * tightness * tightness * (item_size as f64);

    // Penalize large dead space, especially small residuals that few future items can use.
    if post_residual > 0 {
        let dead = post_residual as f64;
        let usable = if next_item_size > 0 && next_item_size <= post_residual { 1.0 } else { 0.0 };
        score += 0.35 * dead * (1.0 - 0.5 * usable);
        // Extra penalty when dead space is below the minimum plausible item size band.
        if post_residual < 10 {
            score += 25.0;
        }
    }

    // Lookahead: reward bins whose residual can also host the next item (chaining).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
        // Extra reward if the chain leaves a still-reasonable residual.
        let chain_res = post_residual - next_item_size;
        if chain_res <= bin_capacity / 2 {
            score -= 3.0;
        }
    } else if next_item_size > post_residual && next_item_size > 0 {
        // If next item cannot use this residual at all, dead space is more acceptable here.
        score += 0.15 * (post_residual as f64);
    }

    // Last-chance bin: if this is the only fitting bin, favor using it to avoid a new bin.
    if fitting_bins_count <= 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: opening a bin is expensive early, cheaper late.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin; decay with progress (sunk bins matter less late).
        score += 55.0 * (1.0 - 0.45 * progress);
        // More open bins => slight extra reluctance to open yet another.
        score += 1.2 * (open_bins_count as f64).sqrt();
        // If many bins fit the item, opening a new one is rarely justified.
        if fitting_bins_count > 0 {
            score += 18.0;
        }
        // If next item is huge and no bin chains, a fresh bin can be attractive.
        if next_item_size > 0 && next_item_size + item_size > bin_capacity {
            score -= 10.0;
        }
    }

    // Global state coupling: prefer bins below mean residual when mean is high
    // (balances load), prefer above-mean bins when mean is low (consolidation).
    let diff = bin_residual as f64 - mean_residual;
    if mean_residual > bin_capacity as f64 * 0.5 {
        score += 0.05 * diff;
    } else {
        score -= 0.05 * diff;
    }

    // Mild time-horizon adaptation: early stream favors consolidation (tighter fits),
    // late stream tolerates spreading (residual quality matters less).
    score *= 1.0 + 0.15 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1)

    // Base: raw post residual (prefer tight fits)
    let mut score = pr as f64;

    // Smooth polynomial coupling: dead space is worse as the stream progresses
    let progress_weight = 0.5 + 1.5 * progress;
    score += progress_weight * 40.0 * x * x * (1.0 - x);

    // Penalize post residuals that are too small to ever be useful (x small but nonzero)
    // and reward residuals near zero (perfect fit)
    score -= 30.0 * (1.0 - x) * (1.0 - x) * (1.0 - x);

    // Lookahead: reward leaving space for the next item (smooth interaction)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = pr - nxt;
        let gapn = gap / cap;
        // smooth reward when gap is close to zero or comfortably positive
        score -= 15.0 * (-gapn * gapn * 8.0).exp();
        // penalize when next item barely fits or doesn't fit
        score += 10.0 * (1.0 / (1.0 + gap.abs()));
    }

    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: mildly penalize opening a new bin early, allow it late
    // or when the item is large and residual is tight
    if bin_residual == bin_capacity {
        let openness = 0.6 * progress - 0.4 * (1.0 - progress);
        score += 12.0 + 30.0 * openness - 10.0 * (item_size as f64 / cap);
        // if no open bin fits (fitting_bins_count == 0 handled by caller), new bin is fine
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Mild preference for bins with larger residuals (waste big space on big items)
    score -= 0.05 * bin_residual as f64 * (item_size as f64 / cap);

    // Coupling with mean residual: avoid draining bins below the mean unnecessarily
    score += 3.0 * (pr as f64 - mean_residual) / cap;

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    let cap = bin_capacity.max(1) as f64;
    let post = post_residual as f64;
    let next = next_item_size as f64;
    let open = open_bins_count as f64;
    let fitting = fitting_bins_count as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let mean_norm = (mean_residual / cap).clamp(0.0, 1.0);
    let item_norm = (item_size as f64 / cap).clamp(0.0, 1.0);
    let open_pressure = open / (open + 5.0);
    let is_new_bin = bin_residual == bin_capacity;

    // Mutated base: slight item-size coupling to break ties toward fuller bins.
    let mut score = post * 0.95 + item_norm * 0.05;

    // Reward exact closure, scaled by how crowded the bin set is.
    if post_residual == 0 {
        score -= cap * (0.24 + 0.30 * open_pressure + 0.10 * progress);
    }

    // Dead-space avoidance with convex boost for thin slivers.
    let dead_limit = next.max(0.10 * cap);
    if post > 0.0 && post < dead_limit {
        let missing = dead_limit - post;
        let mut dead_weight = 2.4 + 1.3 * open_pressure + 0.6 * progress + 0.5 * mean_norm;
        let thinness = 1.0 - post / dead_limit;
        if thinness > 0.7 {
            dead_weight += (thinness - 0.7) * 3.0;
        }
        score += missing * dead_weight;
    }

    // Breaking the immediate lookahead chain is a serious fragmentation cost.
    if next > 0.0 && post > 0.0 && post < next {
        score += cap * (0.45 + 0.35 * (1.0 - post / next));
    }

    // Reward placements that leave just enough room for the next item.
    if next > 0.0 && post >= next {
        let slack = ((post - next) / cap).clamp(0.0, 1.0);
        let tightness = 1.0 - slack * slack;
        score -= cap * (0.18 + 0.07 * progress) * tightness;

        let ratio = post / next;
        let mult_err = (ratio - ratio.round()).abs();
        if mult_err < 0.02 {
            score -= cap * 0.06 * (1.0 - 0.5 * progress);
        }
    }

    // Two-step lookahead: stranded tiny gaps late in the stream.
    if post > 0.0 && next > 0.0 && post < next && post < 0.06 * cap {
        score += cap * (0.15 + 0.20 * progress);
    }

    // Fragmentation-anticipation in the awkward band above next item.
    if !is_new_bin && post > next && next > 0.0 {
        let awkward = (next + mean_residual.min(cap)).min(cap);
        if post < awkward {
            let depth = 1.0 - (awkward - post) / awkward.max(1.0);
            score += cap * 0.08 * depth * (0.5 + 0.5 * progress);
        }
    }

    if is_new_bin {
        let fit_pressure = fitting.min(4.0);
        let mut new_penalty = cap
            * (0.18 + 0.45 * open_pressure + 0.10 * mean_norm + 0.05 * fit_pressure)
            * (1.10 - 0.25 * item_norm);

        if next > 0.0 && post < next {
            new_penalty += cap * (0.70 + 0.25 * (1.0 - post / next));
        }

        new_penalty += cap * 0.10 * progress;

        new_penalty *= 1.0 - 0.15 * (1.0 - mean_norm) * open_pressure;

        if item_norm > 0.90 {
            new_penalty -= cap * 0.35 * (item_norm - 0.90) / 0.10;
        }

        score += new_penalty;
    } else if fitting_bins_count == 1 {
        score -= cap * (0.20 + 0.30 * open_pressure + 0.05 * progress);
    } else if next > 0.0 {
        let ratio = post / next;
        let chain_fit = (ratio.round() - ratio).abs();
        let chain_weight = 0.06 + 0.02 * fitting.min(5.0);
        score += chain_fit * next * chain_weight;
    }

    // Prefer bins whose residual stays usable for the average remaining item.
    if !is_new_bin && post > 0.0 && mean_residual > 0.0 {
        let usable = (post / mean_residual).clamp(0.0, 4.0);
        score += (2.0 - usable).abs() * 0.05 * cap * (1.0 - progress);
    }

    // Compaction reward: prefer the fullest bins after placement.
    if !is_new_bin && post > 0.0 {
        let fill_after = 1.0 - post / cap;
        score -= fill_after * cap * 0.05 * (1.0 - fitting.min(3.0) / 3.0);
    }

    // Residual-parity coupling: post + mean forming a future exact fit.
    if !is_new_bin && post > 0.0 && mean_residual > 1.0 {
        let pair = post + mean_residual;
        let pair_err = (pair / cap - (pair / cap).round()).abs();
        if pair_err < 0.03 && pair <= cap {
            score -= cap * 0.05 * (1.0 - progress);
        }
    }

    // Lookahead anticipation: post-residual just above next item.
    if !is_new_bin && fitting > 1.0 && next > 0.0 && post >= next {
        let gap = post - next;
        if gap > 0.0 && gap < 0.15 * cap {
            score -= cap * 0.10 * (1.0 - gap / (0.15 * cap));
        }
    }

    // NEW: absolute dead-zone penalty on small post-residuals regardless of
    // next-item size — attacks residual-variance directly.
    let frag = if post > 0.0 { (post / cap).clamp(0.0, 1.0) } else { 0.0 };
    let frag_zone = 0.10 * (1.0 - progress) + 0.04;
    if !is_new_bin && frag > 0.0 && frag < frag_zone {
        let frag_sev = 1.0 - frag / frag_zone;
        score += cap * frag_sev * (0.08 + 0.12 * open_pressure + 0.06 * mean_norm);
        if next > 0.0 && next > post {
            score += cap * 0.10 * frag_sev;
        }
    }

    // NEW: multi-fit chain potential — post-residual a clean multiple of next.
    if !is_new_bin && fitting_bins_count >= 2 && next > 0.0 && post >= next {
        let alt_ratio = post / next;
        if alt_ratio.fract() < 0.15 && alt_ratio >= 2.0 {
            score -= cap * 0.04 * (1.0 - progress);
        }
    }

    // NEW: two-in-a-row potential — reward post in [next, 2*next).
    if !is_new_bin && post > next && next > 0.0 && post < 2.0 * next {
        score -= cap * 0.03 * (1.0 - 0.5 * progress) * (1.0 - (post / next - 1.0));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modular structure on capacity fractions
    let post = post_residual;
    let class = post / 10; // harmonic band: 0..10
    let phase = post % 10; // within-band phase

    // Reward small post_residual, but with harmonic banding
    score -= (10.0 - class as f64) * 1.5;

    // Penalize residual in "dead zone" classes: too small for typical items (1..100 range)
    // class 0 (residual < 10) is near-perfect; class 1..2 (10..29) is awkward dead space
    if class >= 1 && class <= 2 {
        score += 8.0 - phase as f64 * 0.3;
    }
    // class 3..5 (30..59): medium usable
    if class >= 3 && class <= 5 {
        score -= 2.0;
    }
    // class 6..9 (60..99): large, good for future big items
    if class >= 6 && class <= 9 {
        score -= 4.0 + (phase as f64) * 0.1;
    }

    // Coupling with next item: does post_residual admit next_item_size?
    if next_item_size > 0 {
        if post >= next_item_size {
            // exact-fit lookahead reward: next item then leaves small residual
            let chained = post - next_item_size;
            let chain_class = chained / 10;
            score -= 6.0 - chain_class as f64 * 0.5;
            // harmonic bonus when chain leaves another small residual
            if chained % 10 <= 2 {
                score -= 3.0;
            }
        } else {
            // post_residual cannot host next item: penalize proportionally to gap
            let gap = (next_item_size - post) as f64;
            score += gap * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening unless current bin would waste a lot
    if bin_residual == bin_capacity {
        let waste = post_residual as f64;
        score += 20.0;
        // allow new bin late in stream or when mean residual is high (bins fragmented)
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 8.0 + (mean_residual - cap * 0.5).max(0.0) * 0.1;
        // still prefer new bin if item is huge relative to typical residual
        if item_size as f64 > mean_residual + 10.0 {
            score -= 15.0;
        }
        let _ = waste;
    }

    // Mild preference for filling bins tightly relative to mean residual
    score -= (mean_residual - post_residual as f64).max(0.0) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), but treat very small gaps
    // (< 10% of capacity) as unusable dead space -> strong penalty.
    let dead_threshold = (bin_capacity as f64 * 0.10).max(1.0);
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 8.0;
    }

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 50.0;
    } else if (post_residual as f64) <= dead_threshold * 0.5 {
        score -= 15.0;
    }

    // Perfect-fit lookahead: if the next item exactly fills post_residual,
    // strongly favor this bin (chained packing).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // next item fits here: mild bonus proportional to how well it fits.
        score -= (post_residual - next_item_size) as f64 * 0.3;
    } else if next_item_size > post_residual && post_residual > 0 {
        // next item cannot use this residual: penalize leaving a stranded gap.
        score += (post_residual as f64) * 0.4;
    }

    // Last-chance bin: if this is the only bin that fits, avoid forcing a
    // bad placement unless the fit is genuinely good.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
        if post_residual as f64 > dead_threshold {
            score -= 5.0;
        }
    }

    // Open-bin pressure: many open bins -> discourage spreading into new
    // bins; favor consolidating into existing ones.
    score -= (open_bins_count as f64).sqrt() * 2.0;

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when existing bins would leave large dead space.
    if bin_residual == bin_capacity {
        // Baseline attractiveness of a fresh bin.
        score = (bin_capacity - item_size) as f64 * 0.9;
        // Prefer opening a new bin when current bins are fragmented
        // (mean residual small relative to what we need to leave).
        let fragmentation = mean_residual / bin_capacity as f64;
        score -= fragmentation * 15.0;
        // If many bins already open and this is a big item, new bin is good.
        if item_size >= bin_capacity / 2 {
            score -= 10.0;
        }
        // If no other bin fits at all, the new bin must win.
        if fitting_bins_count == 0 {
            score -= 1000.0;
        }
    } else if fitting_bins_count == 0 {
        // Existing bin can't take it (shouldn't be called), make unattractive.
        score += 1000.0;
    }

    // Mild time-dependent tightening: late in stream, prefer exact fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: penalize wasted space quadratically, scaled by capacity.
    let waste = post_residual as f64;
    score += 0.35 * (waste * waste) / bin_capacity as f64;

    // 2-step lookahead: reward bins whose post_residual exactly (or nearly) matches next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 22.0 * (-gap / 12.0).exp();
        // If next item fits perfectly after this placement, strong bonus.
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Penalize leaving a residual too small for the next item (dead space).
        if post_residual < next_item_size && post_residual > 0 {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: simply prefer tightest fit.
        score += 0.2 * waste;
    }

    // Relative-to-mean coupling: prefer placing into bins with below-average residual
    // (consolidate fullness) unless it's a perfect lookahead match.
    let rel = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 6.0 * rel;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: make empty bin attractive only when no open bin
    // fits well; otherwise keep it moderately penalized so existing bins are used.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 14.0;
        // But if current item is large relative to capacity, new bin is fine.
        score -= 0.08 * item_size as f64;
        // Late in the stream, slightly discourage proliferation of open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 8.0 * progress;
        // If many open bins already, discourage another one.
        score += 0.4 * open_bins_count as f64;
        // If next item is huge and wouldn't fit the residual anyway, new bin is fine.
        if next_item_size > item_size {
            score -= 6.0;
        }
    }

    // Mild preference for filling nearly-full bins.
    let fullness = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= 4.0 * fullness;

    score
}

