pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are excellent: reward small post_residual non-linearly.
    let pr = post_residual as f64;
    score -= (bin_capacity as f64 - pr).sqrt() * 2.0;

    // Penalize dead space: residuals too small for the smallest plausible item.
    if post_residual < 10 && bin_residual != bin_capacity {
        score += 25.0;
    }

    // Lookahead coupling: if next item fits in post_residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 + 0.15 * next_item_size as f64;
        } else {
            // Next item won't fit here; penalize wasting a "good" bin.
            score += 0.10 * next_item_size as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // Many options: prefer the bin where the item fits most snugly,
        // slight penalty to spread attention across tightness.
        score += 0.5 * (fitting_bins_count as f64 - 1.0);
    }

    // Global state: many open bins -> prefer filling existing ones (compactness).
    let t = step_index as f64 / (total_items.max(1) as f64);
    let crowd = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    score += crowd * 0.4 * (0.5 + t);

    // Mean residual coupling: high mean residual means bins are loose;
    // prefer bins below mean residual (tighter than average).
    score += 0.08 * (mean_residual - bin_residual as f64);

    // New-bin candidate logic: opening a new bin is only good when the item
    // is large and would leave a bad residual in any existing bin, or when
    // existing bins are very tight on average.
    if bin_residual == bin_capacity {
        let bad_fit = if fitting_bins_count == 0 { 0.0 } else {
            (bin_residual - item_size) as f64
        };
        let avg_waste = mean_residual - item_size as f64;
        if avg_waste < 5.0 {
            score -= 20.0; // existing bins are tight; new bin is fine
        } else {
            score += 10.0 + 0.1 * avg_waste; // discourage opening new bins
        }
        let _ = bad_fit;
        // Late in the stream, avoid opening new bins aggressively.
        score += 15.0 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    // normalized post-residual in [0,1]
    let t = pr / cap;

    let mut score = pr as f64;

    // Non-linear polynomial coupling: penalize small-but-nonzero dead space quadratically
    score += 40.0 * (1.0 - t) * t * t;

    // Stream-progress coupling: early on, tolerate imperfect fits; late, demand tight fits
    let progress_weight = 0.35 * progress * progress + 0.15 * progress;
    score -= progress_weight * (cap - pr);

    // Reward tight fits more strongly as progress advances
    score += progress * 2.0 * t;

    // Last-chance bin: strong bonus to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: make empty bins mildly attractive only when
    // the item would leave a bad fit elsewhere or stream is early
    if bin_residual == bin_capacity {
        let early_bonus = 8.0 * (1.0 - progress);
        score -= early_bonus;
        // penalize opening new bins when many are already open and could fit
        score += 0.5 * open_bins_count as f64;
    }

    // Lookahead: if next item fits exactly into the post-residual, reward this bin
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let slack = pr - nx;
            score -= 12.0 * (1.0 - slack / cap);
        } else {
            score += 3.0 * (nx - pr) / cap;
        }
    }

    // Mean-residual divergence penalty: prefer bins near the mean residual (balanced packing)
    score += 0.3 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: residues divisible by 10 are "usable" classes,
    // odd/prime-ish residues are dead-space prone.
    let r = post_residual;
    let class = r % 10;
    if r > 0 {
        if class == 0 {
            score -= 6.0; // perfectly harmonic residue, highly reusable
        } else if class == 5 {
            score -= 2.5;
        } else if class % 2 == 0 {
            score -= 1.0;
        } else {
            score += 3.0; // odd non-5 residues are poor fit targets
        }
    }

    // Integer-division thresholds on post_residual relative to typical small items
    let usable_slots = r / 10; // how many smallest items could still fit
    score -= (usable_slots as f64) * 1.5;

    // Lookahead: reward if next item fits exactly into post-residual (perfect chaining)
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 25.0;
        } else if next_item_size <= r {
            let slack = r - next_item_size;
            score -= 8.0 - (slack as f64) * 0.15;
            // harmonic match between next item and residual class
            if (next_item_size % 10) == class {
                score -= 4.0;
            }
        } else {
            score += 5.0; // next item won't fit here anyway
        }
    } else {
        // last item: just minimize waste
        score += (r as f64) * 0.1;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // New-bin candidate: only attractive when open bins are crowded / fragmented
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 40.0 + open_bins_count as f64 * 2.0 - pressure * 20.0 - progress * 10.0;
        if next_item_size > 0 && next_item_size > mean_residual as u32 {
            score -= 12.0; // nothing open will hold the next item either
        }
    }

    // Mild bonus for tightening well-packed bins (low residual already)
    if r > 0 && r <= 10 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    let cap = bin_capacity.max(1) as f64;
    let post = post_residual as f64;
    let next = next_item_size as f64;
    let open = open_bins_count as f64;
    let fitting = fitting_bins_count as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let mean_norm = (mean_residual / cap).clamp(0.0, 1.0);
    let item_norm = (item_size as f64 / cap).clamp(0.0, 1.0);
    let open_pressure = open / (open + 5.0);
    let is_new_bin = bin_residual == bin_capacity;

    // Combined base: residual minimization blended with fill-level preference.
    let mut score = post * 0.95 + item_norm * 0.05;

    // Reward exact closure, scaled by how crowded the bin set is.
    if post_residual == 0 {
        score -= cap * (0.24 + 0.30 * open_pressure + 0.10 * progress);
    }

    // Dead-space avoidance with convex severity for tiny stranded slivers.
    let dead_limit = next.max(0.10 * cap);
    if post > 0.0 && post < dead_limit {
        let missing = dead_limit - post;
        let severity = 1.0 + (1.0 - post / dead_limit).powi(2);
        let dead_weight = (2.4 + 1.3 * open_pressure + 0.6 * progress + 0.5 * mean_norm) * severity;
        score += missing * dead_weight;
    }

    // Breaking the immediate lookahead chain is a serious fragmentation cost.
    if next > 0.0 && post > 0.0 && post < next {
        score += cap * (0.45 + 0.35 * (1.0 - post / next));
    }

    // Reward placements that leave just enough room for the next item,
    // with a tighter quadratic curve favoring snug fits.
    if next > 0.0 && post >= next {
        let slack = ((post - next) / cap).clamp(0.0, 1.0);
        let tightness = 1.0 - slack * slack;
        score -= cap * (0.18 + 0.07 * progress) * tightness;

        // Exact-multiple chain potential: post_residual a clean multiple of
        // next_item_size enables a sequence of future perfect fits.
        let ratio = post / next;
        let mult_err = (ratio - ratio.round()).abs();
        if mult_err < 0.02 {
            score -= cap * 0.06 * (1.0 - 0.5 * progress);
        }
    }

    // Two-step lookahead: stranded tiny gaps late in the stream.
    if post > 0.0 && next > 0.0 && post < next && post < 0.06 * cap {
        score += cap * (0.15 + 0.20 * progress);
    }

    // Fragmentation-anticipation: residuals in the awkward band just above
    // the next item but below next + mean item likely become dead space.
    if !is_new_bin && post > next && next > 0.0 {
        let awkward = (next + mean_residual.min(cap)).min(cap);
        if post < awkward {
            let depth = 1.0 - (awkward - post) / awkward.max(1.0);
            score += cap * 0.08 * depth * (0.5 + 0.5 * progress);
        }
    }

    if is_new_bin {
        let fit_pressure = fitting.min(4.0);
        let mut new_penalty = cap
            * (0.18 + 0.45 * open_pressure + 0.10 * mean_norm + 0.05 * fit_pressure)
            * (1.10 - 0.25 * item_norm);

        // A new bin that cannot absorb the next item is especially wasteful.
        if next > 0.0 && post < next {
            new_penalty += cap * (0.70 + 0.25 * (1.0 - post / next));
        }

        // Late in the stream, opening bins is nearly always wasteful.
        new_penalty += cap * 0.10 * progress;

        // Relax penalty when current bins are already highly fragmented.
        new_penalty *= 1.0 - 0.15 * (1.0 - mean_norm) * open_pressure;

        // Opening is attractive when the item nearly fills a fresh bin.
        if item_norm > 0.90 {
            new_penalty -= cap * 0.35 * (item_norm - 0.90) / 0.10;
        }

        // When no next item exists, opening is less harmful late in the stream.
        if next == 0.0 {
            new_penalty -= cap * 0.05 * (1.0 - progress);
        }

        score += new_penalty;
    } else if fitting_bins_count == 1 {
        // Strongly prefer the last open bin that can still take the item.
        score -= cap * (0.20 + 0.30 * open_pressure + 0.05 * progress);
    } else if next > 0.0 {
        // Chain-fit preference: reward residuals close to a multiple of the
        // next item size, scaled by how many competing bins exist.
        let ratio = post / next;
        let chain_fit = (ratio.round() - ratio).abs();
        let chain_weight = 0.06 + 0.02 * fitting.min(5.0);
        score += chain_fit * next * chain_weight;
    }

    // Prefer bins whose residual stays usable for the average remaining item.
    if !is_new_bin && post > 0.0 && mean_residual > 0.0 {
        let usable = (post / mean_residual).clamp(0.0, 4.0);
        score += (2.0 - usable).abs() * 0.05 * cap * (1.0 - progress);
    }

    // Compaction reward: prefer the fullest bins after placement, strongest
    // when few alternative bins compete.
    if !is_new_bin && post > 0.0 {
        let fill_after = 1.0 - post / cap;
        score -= fill_after * cap * 0.05 * (1.0 - fitting.min(3.0) / 3.0);
    }

    // Fragmentation zone: penalize residuals that are too small to be useful,
    // severity decaying with progress.
    let frag = if post > 0.0 { (post / cap).clamp(0.0, 1.0) } else { 0.0 };
    let frag_zone = 0.10 * (1.0 - progress) + 0.04;
    if frag > 0.0 && frag < frag_zone {
        let frag_sev = 1.0 - frag / frag_zone;
        score += cap * frag_sev * (0.08 + 0.12 * open_pressure + 0.06 * mean_norm);
        if next > 0.0 && next > post {
            score += cap * 0.10 * frag_sev;
        }
    }

    // Multi-step chain potential: post is a clean multiple (>= 2) of next.
    if !is_new_bin && fitting_bins_count >= 2 && next > 0.0 && post >= next {
        let alt_ratio = post / next;
        if alt_ratio.fract() < 0.15 && alt_ratio >= 2.0 {
            score -= cap * 0.04 * (1.0 - progress);
        }
    }

    // Snug double-fit band: residual fits the next item roughly twice.
    if !is_new_bin && post > 0.0 && next > 0.0 && post >= next && post < 2.0 * next {
        score -= cap * 0.03 * (1.0 - 0.5 * progress) * (1.0 - (post / next - 1.0));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps are unusable dead space.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 - (post_residual as f64) * 5.0; // gap=1 worst (+55), gap=10 (+10)
    } else if post_residual > 10 && post_residual <= 20 {
        score += 8.0; // moderately awkward residual
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits proportionally: waste ratio penalty.
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += waste_ratio * 25.0;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a bin is costly when open bins exist
    // and pressure is low; encourage it only when open bins are fragmented.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / (mean_residual / bin_capacity as f64).max(0.1);
        score += 45.0;
        if open_bins_count > 2 && mean_residual < 25.0 {
            score -= 20.0; // existing bins are nearly full; new bin is reasonable
        }
        if pressure > 8.0 {
            score -= 10.0;
        }
        if next_item_size as f64 > mean_residual {
            score -= 15.0; // next item won't fit typical residual; new bin useful
        }
    }

    // Lookahead: if next item exactly fits the post residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 6.0; // next item can't use this gap; slight penalty
    }

    // Open-bin pressure: mildly discourage spreading across many bins.
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
