    // necessary or it yields a perfect 2-step lookahead fit.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let perfect_chain = next_item_size > 0 && post_residual == next_item_size;
        if perfect_chain {
            score -= 60.0; // new bin exactly fits the next item too
        } else {
            score += 45.0 + (open_bins_count as f64).sqrt() * 5.0;
        }
    }

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual == next_item_size {
            score -= 55.0; // perfect follow-up placement
        } else {
            let slack = (post_residual - next_item_size) as f64;
            // Small slack after next item is good; large slack is wasted space.
            score -= 20.0 - slack * 0.3;
        }
    } else if next_item_size > 0 {
        // Next item cannot follow into this bin: penalize dead space,
        // scaled by how much of the residual is stranded.
        let dead = post_residual as f64;
        score += dead * 0.5;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one.
    if !is_new_bin && fitting_bins_count == 1 && post_residual <= bin_capacity - 10 {
        score -= 15.0;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor).
    score -= (mean_residual - post_residual as f64) * 0.2;

    // Slight late-stream tightening: as stream progresses, prefer fuller bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 2.0;

    score
}

