pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space: residuals too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 4.0;
    }

    // Perfect fill is heavily rewarded.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // Next item won't fit here; mildly penalize wasting a very tight bin.
            score += 3.0 * tightness;
        }
    } else {
        // Last item: just minimize post residual (already base score).
        score -= 5.0 * tightness;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Crowding: many open bins -> consolidate into already-open bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let crowding = (open_bins_count as f64) / (1.0 + mean_residual / 10.0);
    score += 0.35 * crowding * (0.5 + progress);

    // Global residual pressure: high mean residual means space is abundant;
    // be pickier (penalize loose fits). Low mean residual -> accept more.
    let mean_res = mean_residual.clamp(0.0, bin_capacity as f64);
    let pickiness = mean_res / (bin_capacity as f64);
    score += 10.0 * pickiness * (post_residual as f64) / (bin_capacity as f64);

    // New empty bin candidate: only attractive when it enables a great
    // two-item combo with the lookahead, or no open bin fits well.
    if bin_residual == bin_capacity {
        let combo_bonus = if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            6.0 + 10.0 * (1.0 - (item_size + next_item_size) as f64 / (bin_capacity as f64))
        } else {
            0.0
        };
        let escape_bonus = if fitting_bins_count == 0 { 0.0 } else { 14.0 };
        // Base cost of a fresh bin: its full post residual (large), softened
        // slightly by combo potential.
        score += 8.0 - combo_bonus + escape_bonus + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
