    score -= 1.6 * tightness * tightness * (0.5 + progress);

    // Coupling with mean residual: prefer bins whose residual deviates smoothly
    let dev = norm_pr - mean_r;
    score += 0.4 * dev * dev - 0.5 * dev * (1.0 - progress);

    // Next-item lookahead: smooth reward if next item fits the post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64 / cap;
        let fit_gap = (norm_pr - nxt).abs();
        let fits_next = if nxt <= norm_pr { 1.0 } else { 0.0 };
        score -= 0.9 * fits_next * (1.0 - fit_gap) * (0.4 + 0.6 * progress);
        score += 0.5 * fit_gap * fit_gap * (1.0 - progress);
    }

    // Last-chance bonus (smooth sigmoid-like on fitting_bins_count)
    let scarcity = 1.0 / (fitting_bins_count as f64 + 1.0);
    score -= 1.2 * scarcity * scarcity * (0.3 + 0.7 * progress);

    // Mild penalty for spreading across many bins early
    score += 0.15 * (open_bins_count as f64 / (open_bins_count as f64 + 4.0)) * (1.0 - progress);

    // New-bin candidate: make empty bins moderately attractive only for large items / poor fits
    if bin_residual == bin_capacity {
        let large_item = norm_item * norm_item;
        score += 0.25 + 1.3 * large_item * (1.0 - progress) - 0.6 * large_item * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Harmonic class of post_residual: residual mod 10 buckets
    let r = post_residual;
    let class = (r % 10) as f64;
    let zero_class = (r % 10 == 0) as i32;
    let five_class = (r % 10 == 5) as i32;

    // Reward residuals that align with decadal classes (likely to fit future items)
    score -= 12.0 * zero_class as f64;
    score -= 5.0 * five_class as f64;
    score -= 0.15 * class;

    // Integer-division thresholds: post_residual in [1..=5] is dead space
    if r > 0 && r <= 5 {
        score += 40.0;
    } else if r <= 10 && r > 0 {
        score += 15.0;
    }

    // Coupling with next item size (lookahead): does next item fit in post_residual?
    if next_item_size > 0 {
        if next_item_size <= r {
            // next item fits: reward tight packing
            let slack = (r - next_item_size) as f64;
            score -= 18.0 * (1.0 - slack / cap);
            if r % next_item_size.max(1) == 0 {
                score -= 10.0; // perfect divisor coupling
            }
        } else {
            // next item does not fit here: penalize proportionally
            score += 8.0 + 0.2 * ((next_item_size - r) as f64);
        }
    } else {
        // last item: prefer minimal residual
        score += 0.5 * r as f64;
    }

    // Capacity fraction coupling: item size relative to capacity
    let frac = item_size as f64 / cap;
    if frac > 0.5 {
        score -= 10.0 * frac; // big items prefer existing bins to avoid waste
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: only prefer fresh bin when item is huge
    // and no good harmonic fit exists.
    if bin_residual == bin_capacity {
        let base = 25.0 + 0.3 * r as f64;
        // penalize opening new bins early in the stream
        let progress = step_index as f64 / total_items.max(1) as f64;
        let penalty = base * (1.0 + 0.5 * (1.0 - progress)) + 2.0 * open_bins_count as f64;
        score += penalty;
        // but if item nearly fills a bin alone, new bin is fine
        if frac > 0.85 {
            score -= 45.0;
        }
        if next_item_size > 0 && next_item_size >= 60 {
            score -= 10.0; // large next item benefits from fresh capacity
        }
    }

    // Slight tie-break toward bins below mean residual (denser bins)
    score += 0.05 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for the smallest
    // plausible item are "dead" and should be heavily penalized.
    let dead_threshold: u32 = 10;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 25.0 * (dead_threshold - post_residual) as f64;
    }
    if post_residual == 0 {
        score -= 10.0; // perfect fit is excellent
    }

    // Last-chance pressure: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing
    // bins; few open bins -> opening a new bin is cheaper.
    let bin_pressure = open_bins_count as f64 / (1.0 + mean_residual.max(0.0) / 20.0);
    score += 0.35 * bin_pressure * (post_residual as f64 / bin_capacity as f64);

    // Lookahead: if the next item fits exactly in the post-residual, reward it.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 22.0;
    }
    // Penalize if next item cannot use the leftover gap at all.
    if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
        score += 6.0;
    }

    // New-bin candidate handling: only attractive when existing bins are tight
    // or the stream is early (long horizon to amortize a fresh bin).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let tightness = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score += 30.0 * tightness + 15.0 * (1.0 - progress);
        // A new bin is bad if an open bin gives a good (small) residual.
        score += 0.8 * (bin_capacity - post_residual) as f64;
    }

    // Mild preference for tighter existing fits overall.
    score += 0.15 * (bin_residual as f64 - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let is_new_bin = bin_residual == bin_capacity;

    // --- 2-step lookahead: reward exact / near-exact match with next item ---
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            // Perfect wrap: next item exactly fills the remainder
            if gap == 0.0 {
                score -= 60.0;
            } else if gap <= 10.0 {
                score -= 30.0 - gap * 2.0;
            } else {
                // mild reward proportional to how well next item fits
                score -= (next_item_size as f64) * 0.3;
            }
        } else {
            // next item cannot use the leftover: dead-space penalty scaled by waste
            let waste = (next_item_size - post_residual) as f64;
            score += waste * 0.5;
        }
    } else {
        // last item: just minimize leftover
        score += post_residual as f64 * 0.2;
    }

    // --- Compare post_residual against mean residual (avoid fragmenting) ---
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.4;
    } else {
        score -= (mean_residual - post_residual as f64) * 0.2;
    }

    // --- Last-chance bonus: only one bin can fit the item ---
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0;
    }

    // --- New-bin candidate handling ---
    if is_new_bin {
        // Opening a new bin is fine early, penalized when many bins are open
        // and when a decent existing fit exists.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 40.0 + 30.0 * progress + (open_bins_count as f64) * 2.0;
        // If no open bin fits, new bin becomes attractive
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // --- Prefer tight fits overall ---
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 10.0;

    // --- Penalize leaving very small unusable slivers ---
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

