pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (low post_residual is good).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that the lookahead item cannot use.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 4.0; // lookahead can still fit here: good chain
        } else if post_residual > 0 {
            score += 0.05 * (post_residual as f64); // wasted sliver
        }
        // If lookahead exactly matches post_residual, big bonus.
        if post_residual == next_item_size {
            score -= 10.0;
        }
    } else {
        // Last item: just minimize waste.
        score -= 6.0 * fit_ratio;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }
    // Many alternatives: mild penalty to keep options open for small items.
    if fitting_bins_count > 3 {
        score += 1.5;
    }

    // Time-horizon coupling: early in the stream, be conservative (favor new bins
    // for good organization); late in the stream, fill aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * fit_ratio;
    score += 3.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // Global state: if mean residual is high, open bins are loose — prefer
    // consolidating into them; if mean residual is low, opening a new bin
    // (full residual = capacity) is relatively attractive.
    let mean_r = if mean_residual.is_finite() { mean_residual } else { bin_capacity as f64 };
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive when item is large or mean residual is tight.
        score += 0.4 * mean_r;
        score -= 0.3 * item_size as f64;
        // Penalize new bins when plenty of open bins exist already.
        score += 0.15 * open_bins_count as f64;
        // But early stream, new bins are cheap.
        score -= 6.0 * (1.0 - progress);
    } else {
        score -= 0.2 * (bin_residual as f64 - mean_r);
    }

    // Nonlinear dead-space shaping: residuals below 10 are nearly unusable.
    if post_residual < 10 && post_residual > 0 {
        score += 8.0;
    }
    // Perfect power-of-ten residuals are reusable.
    if post_residual == 0 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Smooth polynomial coupling of post_residual with stream progress.
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap;
    let poly = prn * prn * (1.0 - prn) * (1.0 - prn); // peaks at half-full fill
    score -= 60.0 * poly * (0.5 + progress);

    // Reward tight fits, more aggressively late in the stream.
    let tightness = (item_size as f64) / (bin_residual.max(1) as f64);
    score -= 25.0 * tightness * tightness * (0.4 + 0.6 * progress);

    // Penalize leaving dead space that no plausible next item can use.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += 12.0 * (nxt - pr) / cap;
        } else {
            score -= 8.0 * (1.0 - ((pr - nxt) / cap).min(1.0)) * progress;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 - prn);
    }

    // Mild penalty for spreading across many open bins early on.
    score += (open_bins_count as f64).ln() * 2.0 * (1.0 - progress);

    // New-bin candidate: prefer it only when remaining space would be dead space.
    if bin_residual == bin_capacity {
        score -= 5.0 * prn * (1.0 - progress);
        if next_item_size > 0 && (next_item_size as f64) > pr {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "reusable" the leftover space is.
    // Residuals that are multiples of common item sizes (or large classes) are valuable.
    let pr = post_residual;
    let class = if pr == 0 {
        0.0 // perfect fit: best possible
    } else if pr > 50 {
        0.0 // large leftover still usable by most items
    } else if pr % 10 == 0 {
        1.0 // aligned to decile: still commonly matchable
    } else if pr % 5 == 0 {
        3.0
    } else if pr < 10 {
        6.0 // tiny dead space
    } else {
        4.5
    };
    score += class * 2.0;

    // Penalize leaving residual in the "dead zone" (10..20) that few items can use,
    // but reward exact zero.
    if pr > 0 && pr < 20 {
        score += 5.0;
    }
    if pr == 0 {
        score -= 15.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 12.0;
        } else if next_item_size <= pr && next_item_size >= pr / 2 {
            score -= 6.0;
        } else if next_item_size > pr {
            // next item won't fit here; leftover likely wasted
            score += (next_item_size - pr) as f64 * 0.05;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // New-bin candidate logic: an empty bin should only win when existing fits are poor.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 10.0;
        // cheaper to open new bin early in stream (long horizon amortizes)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 6.0 * (1.0 - progress);
        // if item would leave a tiny unusable remainder in any bin, opening fresh is better
        if pr > 0 && pr < 15 && bin_residual >= item_size {
            score -= 9.0;
        }
        if next_item_size > 0 && next_item_size > pr && pr > 0 && bin_residual >= item_size {
            score -= 4.0;
        }
    }

    // Slight preference for tightest existing fit already captured by post_residual;
    // add mild penalty for bins far below mean residual (fragmenting spread).
    score += 0.05 * (mean_residual - bin_residual as f64).abs();

    // Integer-division threshold: residuals in [25,50) are a "golden class".
    if pr >= 25 && pr < 50 && pr % 25 == 0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
