    // Mild penalty for leaving small unusable fragments
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Reward tight fits (small post_residual) non-linearly.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        let tightness = post / cap;
        score += 20.0 * tightness * tightness;
    }

    // Last chance: strongly favor using this bin to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits in the post residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0 + 0.15 * (next_item_size as f64);
    } else if next_item_size > post_residual {
        // Penalize leaving residual that is dead space for the next item.
        score += 0.10 * (post_residual as f64);
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Baseline penalty that shrinks as stream progresses / many bins open.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = (item_size as f64) / cap
            + if fitting_bins_count == 0 { 40.0 } else { 0.0 }
            + if post_residual < 10 { 15.0 } else { 0.0 };
        score = 60.0 - 20.0 * progress + 30.0 * pressure;
        // If next item is large, a fresh bin may be preferable.
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 10.0;
        }
    } else {
        // Prefer bins with residual close to item size relative to mean residual.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // Mild penalty for accumulating many open bins with fragmented space.
    if open_bins_count > 8 {
        score += 0.02 * (open_bins_count as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Smooth non-linear coupling of post_residual with stream progress
    score += 12.0 * norm_pr * norm_pr * (1.0 - t) - 6.0 * norm_pr * t;
    score += 3.0 * (norm_pr * t).sin() * 4.0;

    // Dead-space penalty: small post-residuals that can't fit typical items
    if pr > 0 && pr < 10 {
        score += 15.0 * (1.0 - pr as f64 / 10.0);
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: reward if next item fits the post-residual
    if next_item_size > 0 {
        let fits_next = (post_residual >= next_item_size) as i32 as f64;
        score -= 10.0 * fits_next * (1.0 - t * 0.5);
        score += 5.0 * (next_item_size as f64 / cap) * (1.0 - fits_next);
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // Mean-residual divergence penalty
    score += 0.5 * (pr - mean_residual).abs();

    // New-bin candidate handling: mildly penalize opening new bins early, allow late
    if bin_residual == bin_capacity {
        score += 6.0 * (1.0 - t) + 2.0 * open_bins_count as f64 / 10.0;
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    let cap = bin_capacity.max(1) as f64;
    let post = post_residual as f64;
    let next = next_item_size as f64;
    let open = open_bins_count as f64;
    let fitting = fitting_bins_count as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let mean_norm = (mean_residual / cap).clamp(0.0, 1.0);
    let item_norm = (item_size as f64 / cap).clamp(0.0, 1.0);
    let open_pressure = open / (open + 5.0);
    let is_new_bin = bin_residual == bin_capacity;

    let mut score = post * 0.95 + item_norm * 0.05;

    // Reward exact closure, scaled by how crowded the bin set is.
    if post_residual == 0 {
        score -= cap * (0.24 + 0.30 * open_pressure + 0.10 * progress);
    }

    // Dead-space avoidance with convex severity for tiny stranded slivers.
    let dead_limit = next.max(0.10 * cap);
    if post > 0.0 && post < dead_limit {
        let missing = dead_limit - post;
        let severity = 1.0 + (1.0 - post / dead_limit).powi(2);
        let dead_weight = (2.4 + 1.3 * open_pressure + 0.6 * progress + 0.5 * mean_norm) * severity;
        score += missing * dead_weight;
    }

    // Breaking the immediate lookahead chain is a serious fragmentation cost.
    if next > 0.0 && post > 0.0 && post < next {
        score += cap * (0.45 + 0.35 * (1.0 - post / next));
    }

    // Reward placements that leave just enough room for the next item.
    if next > 0.0 && post >= next {
        let slack = ((post - next) / cap).clamp(0.0, 1.0);
        let tightness = 1.0 - slack * slack;
        score -= cap * (0.18 + 0.07 * progress) * tightness;

        let ratio = post / next;
        let mult_err = (ratio - ratio.round()).abs();
        if mult_err < 0.02 {
            score -= cap * 0.06 * (1.0 - 0.5 * progress);
        }
    }

    // Two-step lookahead: stranded tiny gaps late in the stream.
    if post > 0.0 && next > 0.0 && post < next && post < 0.06 * cap {
        score += cap * (0.15 + 0.20 * progress);
    }

    // Fragmentation zone: penalize residuals that are too small to be useful
    // relative to the capacity, stronger early in the stream.
    let frag = if post > 0.0 { (post / cap).clamp(0.0, 1.0) } else { 0.0 };
    let frag_zone = 0.10 * (1.0 - progress) + 0.04;
    if frag > 0.0 && frag < frag_zone {
        let frag_sev = 1.0 - frag / frag_zone;
        score += cap * frag_sev * (0.08 + 0.12 * open_pressure + 0.06 * mean_norm);
        if next > 0.0 && next > post {
            score += cap * 0.10 * frag_sev;
        }
    }

    // Multi-step chain potential: residual a clean multiple of next item.
    if !is_new_bin && fitting_bins_count >= 2 && next > 0.0 && post >= next {
        let alt_ratio = post / next;
        if alt_ratio.fract() < 0.15 && alt_ratio >= 2.0 {
            score -= cap * 0.04 * (1.0 - progress);
        }
    }

    // Fragmentation-anticipation in the awkward band above next item.
    if !is_new_bin && post > next && next > 0.0 {
        let awkward = (next + mean_residual.min(cap)).min(cap);
        if post < awkward {
            let depth = 1.0 - (awkward - post) / awkward.max(1.0);
            score += cap * 0.08 * depth * (0.5 + 0.5 * progress);
        }
    }

    // Snug-fit bonus when post is just above next.
    if !is_new_bin && post > next && next > 0.0 && post >= next && post < 2.0 * next {
        score -= cap * 0.03 * (1.0 - 0.5 * progress) * (1.0 - (post / next - 1.0));
    }

    if is_new_bin {
        let fit_pressure = fitting.min(4.0);
        let mut new_penalty = cap
            * (0.18 + 0.45 * open_pressure + 0.10 * mean_norm + 0.05 * fit_pressure)
            * (1.10 - 0.25 * item_norm);

        if next > 0.0 && post < next {
            new_penalty += cap * (0.70 + 0.25 * (1.0 - post / next));
        }

        new_penalty += cap * 0.10 * progress;

        new_penalty *= 1.0 - 0.15 * (1.0 - mean_norm) * open_pressure;

        if item_norm > 0.90 {
            new_penalty -= cap * 0.35 * (item_norm - 0.90) / 0.10;
        }

        if next == 0.0 {
            new_penalty -= cap * 0.05 * (1.0 - progress);
        }

        score += new_penalty;
    } else if fitting_bins_count == 1 {
        score -= cap * (0.20 + 0.30 * open_pressure + 0.05 * progress);
    } else if next > 0.0 {
        let ratio = post / next;
        let chain_fit = (ratio.round() - ratio).abs();
        let chain_weight = 0.06 + 0.02 * fitting.min(5.0);
        score += chain_fit * next * chain_weight;
    }

    // Prefer bins whose residual stays usable for the average remaining item.
    if !is_new_bin && post > 0.0 && mean_residual > 0.0 {
        let usable = (post / mean_residual).clamp(0.0, 4.0);
        score += (2.0 - usable).abs() * 0.05 * cap * (1.0 - progress);
    }

    // Compaction reward: prefer the fullest bins after placement.
    if !is_new_bin && post > 0.0 {
        let fill_after = 1.0 - post / cap;
        score -= fill_after * cap * 0.05 * (1.0 - fitting.min(3.0) / 3.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: waste in classes of 10 (capacity fractions)
    let cap_frac = bin_capacity / 10; // = 10
    let waste_class = post_residual / cap_frac; // 0..=10
    score += waste_class as f64 * 3.0;

    // Dead-space penalty: residual too small for any plausible item (min size 1, but
    // small leftovers are only usable for tiny items). Penalize 1..10 hard.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 100.0;
    }

    // Harmonic coupling: does next item fit into post_residual?
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 {
        // next item cannot chain here; mild penalty scaled by closeness
        score += (next_item_size - post_residual) as f64 * 0.2;
    }

    // Last-chance bonus: only bin that fits -> strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin should only win when current bin's
    // post-residual creates bad waste.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score = bin_capacity as f64 * 0.6;
        // discount if item is large relative to capacity (harmonic class of item)
        let item_class = item_size / cap_frac;
        score -= item_class as f64 * 2.0;
        // if no open bins fit, opening is fine
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
        // late in stream, prefer consolidating into existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
        // many open bins -> discourage opening more
        score += open_bins_count as f64 * 1.5;
    }

    // Mean-residual coupling: if this bin is far below mean residual, it's already
    // fragmented; placing here keeps big bins free.
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    // Modulo-arithmetic bonus: post_residual divisible into useful chunks (mod 5 / mod 10)
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 5.0;
    } else if post_residual % 5 == 0 && post_residual > 0 {
        score -= 2.5;
    }

    score
}

