pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item.max(1) * 10 {
        score += 60.0; // gap too small for any realistic item
    }
    // Non-linear penalty: gaps in [1,15] are near-wasted space
    let gap = post_residual as f64;
    if gap > 0.0 && gap <= 15.0 {
        score += (16.0 - gap) * 4.0;
    }

    // Reward tight fits (small post_residual relative to item)
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 25.0;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Open bins pressure: with many open bins, discourage new bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost + pressure; acceptable only if it leaves
        // good space for the lookahead item or existing fits are poor
        let mut nb = 120.0 + pressure * 3.0;
        if next_item_size > 0 {
            let look = next_item_size as f64;
            if look <= 100.0 {
                nb -= 20.0; // fresh bin guarantees room for next item
            }
            if look > bin_capacity as f64 * 0.5 {
                nb -= 15.0; // big next item: fresh bin attractive
            }
        }
        // If this bin is the only fitting bin, make new bin less attractive
        if fitting_bins_count == 1 {
            nb += 50.0;
        }
        score = nb;
    } else {
        // Slight preference toward bins with below-mean residual (consolidate)
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
        // Lookahead synergy: reward residual that can still fit next item
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
        // Penalize leaving a residual that neither fits next item nor is reusable
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
        // Mild open-bin pressure: prefer filling existing bins as count grows
        score -= pressure * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: strongly favor bins where the item leaves almost nothing.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0 + (5 - post_residual) as f64 * 20.0;
    }

    // 2-step lookahead: if the next item fits exactly into post_residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            let chain_waste = post_residual - next_item_size;
            // Reward chaining, but penalize leaving a large dead sliver the next item barely underuses.
            score -= (next_item_size as f64) * 0.5 - (chain_waste as f64) * 0.3;
        } else {
            // Next item cannot fit here; penalize proportional to how far off we are.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.4;
        }
    }

    // Relative-to-mean residual shaping: bins below mean residual are more precious.
    let res = post_residual as f64;
    if mean_residual > 0.0 {
        if res < mean_residual {
            score -= (mean_residual - res) * 0.6;
        } else {
            score += (res - mean_residual) * 0.3;
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // Late in the stream, tighten packing (favor fuller placements even more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= post_residual as f64 * 0.5 * progress;

    // Slight penalty for leaving residual in the awkward 51..70 zone (hard to fill later).
    if post_residual > 50 && post_residual < 70 {
        score += 25.0;
    }

    // New-bin candidate: only attractive when current bin would leave a large unusable gap.
    if bin_residual == bin_capacity {
        // Neutral baseline; competing bins with tight fits will beat it.
        score = post_residual as f64 + 60.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared waste penalty
    score += (post_residual as f64).powi(2) / bin_capacity as f64;

    // Perfect or near-perfect fill gets strong discount
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Last-chance bin: strong bonus to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: if next item fits in post_residual, reward; else penalize dead space
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else {
            // penalize leaving residual too small for next item
            score += (post_residual as f64).min(next_item_size as f64) * 0.15;
        }
    }

    // Prefer filling bins with larger residuals (reduce fragmentation)
    score -= (bin_residual as f64 - mean_residual) * 0.2;

    // Time horizon: late in the stream, be conservative, avoid opening new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: acceptable early, penalized late, unless residual is tiny
        score += 30.0 - 40.0 * progress;
        if post_residual > 0 && fitting_bins_count <= 2 {
            score += 20.0; // don't open new bin when decent fit exists
        }
    } else {
        // Existing bin: more attractive later in the stream
        score -= 10.0 * progress;
    }

    // Many open bins: encourage consolidation
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + progress) - 2.0 * norm_pr * progress + progress * progress * (1.0 - norm_pr);
    score += 20.0 * poly;

    // Reward tight fits (small post_residual) more strongly as stream progresses
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * (30.0 + 40.0 * progress);

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr < ns {
            score += 15.0 * (ns - pr) / cap;
        } else {
            score -= 5.0 * (1.0 - (ns / pr).min(1.0)) * (1.0 + progress);
        }
    }

    // Last-chance bin bonus: avoid opening a new bin needlessly
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Mild penalty when many bins are open and residual is above average (fragmentation)
    if pr as f64 > mean_residual {
        score += 3.0 * (pr - mean_residual) / cap;
    } else {
        score -= 3.0 * (mean_residual - pr) / cap * (1.0 - progress);
    }

    // Encourage consolidation early, diversification late
    score += open_bins_count as f64 * 0.5 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: capacity divided into harmonic slots.
    // Post-residuals that align with a "clean" class (multiples of small divisors)
    // are more likely to absorb future items -> reward them.
    let pr = post_residual;
    let mut class_bonus = 0.0f64;
    if pr == 0 {
        class_bonus -= 60.0; // perfect fill is always best
    } else if pr <= 10 {
        class_bonus -= 25.0; // near-perfect dead space is tiny
    } else if pr % 10 == 0 {
        class_bonus -= 12.0; // decile-aligned residual, easy to fill
    } else if pr % 5 == 0 {
        class_bonus -= 6.0;
    } else if pr % 2 == 0 {
        class_bonus -= 2.0;
    } else {
        class_bonus += 8.0; // odd, awkward residual class
    }

    // Harmonic slot index: integer division thresholds on post_residual.
    let slot = pr / 15; // 15 is a harmonic sub-class of capacity 100 region
    class_bonus -= (6 - slot.min(6)) as f64 * 3.0;

    // Lookahead: reward bins whose post-residual can host the next item exactly.
    if next_item_size > 0 {
        if next_item_size == pr {
            class_bonus -= 40.0; // perfect chain
        } else if next_item_size <= pr {
            class_bonus -= 10.0 + (pr - next_item_size) as f64 * -0.15;
            // small leftover after chaining next item is good
            let chained_left = pr - next_item_size;
            if chained_left % 10 == 0 {
                class_bonus -= 8.0;
            }
        } else {
            class_bonus += 5.0; // next item cannot use this residual
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        class_bonus -= 30.0;
    }

    // New-bin candidate handling: opening a new bin should only win when
    // no open bin offers a decent fit, or the stream is early and we want diversity.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste = bin_capacity as f64 - item_size as f64;
        // Base penalty for opening a new bin; relax early in the stream.
        class_bonus += 45.0 - 25.0 * (1.0 - progress);
        // Large items waste little of a fresh bin; small items waste a lot.
        class_bonus += waste * 0.35;
        // If many bins already fit the item, a new bin is almost never right.
        if fitting_bins_count > 1 {
            class_bonus += 20.0;
        }
        // If the only fitting open bin leaves a huge dead zone, new bin becomes viable.
        if fitting_bins_count == 1 {
            let dead = (bin_residual - item_size) as f64;
            if dead > 30.0 {
                class_bonus -= (dead - 30.0) * 0.4;
            }
        }
    }

    // Prefer bins tighter than the mean residual (better packing density).
    score += (mean_residual - bin_residual as f64) * 0.1;

    // Mild pressure to keep the open-bin count low.
    score += open_bins_count as f64 * 0.05;

    score += class_bonus;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (min size 1..=10)
    // are worthless; penalize them heavily, scaled by how dead they are.
    if post_residual < 10 && post_residual > 0 {
        score += (10 - post_residual) as f64 * 40.0;
    }

    // Semi-dead space: gap below the lookahead item (or typical small item) is risky.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 6.0;
    }

    // Perfect fit reward: exact fill is ideal.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual == item_size {
        score -= 30.0;
    }

    // Open-bin pressure: discourage spreading across many bins; favor closing bins out.
    score += open_bins_count as f64 * 4.0;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // New-bin candidate handling: only attractive when current residuals are poor
    // (mean residual large means open bins are packed/fragmented).
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        // Prefer using existing bins while they remain usable.
        score += 150.0 - pressure * 120.0;
        // Late in the stream, opening fresh bins is less costly.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 40.0;
    } else {
        // Favor tighter fits among open bins: compare residual to mean residual.
        score += (bin_residual as f64 - mean_residual) * 0.5;
    }

    // Reward bins whose post-residual still accommodates the lookahead item (k=2 chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (post_residual - next_item_size).min(30) as f64 * 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize dead space, amplified when next item cannot use it
        let dead = post_residual as f64;
        if next_item_size > 0 && (post_residual as u32) < next_item_size {
            score += dead * 0.8;
        } else {
            score -= dead * 0.3;
        }
    }

    // 2-step lookahead: reward when next item fits exactly in post_residual
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs();
        if diff == 0 {
            score -= 500.0;
        } else {
            score += diff as f64 * 0.5;
        }
    }

    // Last fitting bin: strong reward to use it, avoid opening new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= (mean_residual - post_residual as f64) * 0.4;

    // New-bin candidate: penalize mildly unless current bin fit is bad
    if bin_residual == bin_capacity {
        let bad_fit = if next_item_size > 0 && (post_residual as u32) < next_item_size { 1.0 } else { 0.0 };
        score += 250.0 - 200.0 * bad_fit;
    }

    // Late in stream: prefer filling existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * 20.0;

    // Reward perfect / near-perfect fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 30.0;
    }

    // Last-chance bonus: if this is the only bin that can fit, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Lookahead coupling: if the next item fits in the post-residual, reward;
    // if post-residual is too small for the next item (dead space risk), penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else if post_residual > 0 {
            let waste_ratio = post_residual as f64 / (next_item_size as f64 + post_residual as f64);
            score += waste_ratio * 25.0;
        }
    }

    // Penalize opening new bins when many bins are already open but poorly filled.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_fill = 1.0 - mean_residual / bin_capacity as f64;
        // New bin is attractive only if existing bins are quite full on average
        // and this item is large relative to remaining space elsewhere.
        let new_bin_bonus = 40.0 * (avg_fill - 0.6).max(0.0) + 20.0 * progress;
        score -= new_bin_bonus;
        // Slight base penalty so a new bin never wins on trivial terms.
        score += 5.0;
    } else {
        // Mild reward for using existing bins when mean residual is high (fragmentation risk).
        if mean_residual > bin_capacity as f64 * 0.5 {
            score -= 10.0;
        }
    }

    // Time-horizon effect: early in the stream, be more liberal with new bins;
    // late in the stream, squeeze into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 3.0 * (bin_residual as f64 / bin_capacity as f64);

    // Small penalty proportional to residual to break ties toward fuller bins.
    score += post_residual as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap; // normalized post residual in [0,1]

    // Base: prefer small post residual (tight fit), with a smooth polynomial shaping
    let mut score = pr;

    // Non-linear polynomial coupling: post_residual interacts with stream progress.
    // Early on, waste matters less; late, tight fits matter more.
    let progress_sq = progress * progress;
    let coupling = norm_pr * (1.0 + 2.0 * progress_sq) * cap;
    score += 0.5 * coupling;

    // Reward bins whose residual is too small for the next item (avoids stranding).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = nxt - pr;
        if gap > 0.0 {
            // post residual cannot host next item: penalize proportionally, more so late in stream
            score += gap * (0.5 + 1.0 * progress);
        } else {
            // next item fits exactly-ish: reward smooth quadratic closeness
            score -= (-gap) * (1.0 - (-gap / cap).min(1.0));
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0 + 30.0 * progress;
    }

    // Penalize opening a new bin when open bins exist, scaled by mean residual availability
    if bin_residual == bin_capacity && open_bins_count > 0 {
        let usable = (mean_residual / cap).min(1.0);
        score += 25.0 + 50.0 * usable + 20.0 * (1.0 - progress);
    } else if bin_residual == bin_capacity {
        // first bin ever: slight base penalty so it isn't chosen over nothing spuriously
        score += 0.0;
    }

    // Mild reward for using bins that are relatively fuller than the average
    let fullness = (bin_residual as f64) / cap;
    let mean_fullness = (mean_residual / cap).min(1.0);
    score -= 10.0 * (fullness - mean_fullness).max(0.0);

    // Smooth dead-space penalty: quadratic in small residuals (unusable fragments)
    if pr > 0.0 && pr < 10.0 {
        score += (10.0 - pr) * (10.0 - pr) * 0.05;
    }

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    let cap = bin_capacity.max(1) as f64;
    let post = post_residual as f64;
    let next = next_item_size as f64;
    let open = open_bins_count as f64;
    let fitting = fitting_bins_count as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let mean_norm = (mean_residual / cap).clamp(0.0, 1.0);
    let item_norm = (item_size as f64 / cap).clamp(0.0, 1.0);
    let open_pressure = open / (open + 5.0);
    let is_new_bin = bin_residual == bin_capacity;

    let mut score = post * 0.95 + item_norm * 0.05;

    // Reward exact closure, scaled by how crowded the bin set is.
    if post_residual == 0 {
        score -= cap * (0.24 + 0.30 * open_pressure + 0.10 * progress);
    }

    // Dead-space avoidance with convex severity for tiny stranded slivers.
    let dead_limit = next.max(0.10 * cap);
    if post > 0.0 && post < dead_limit {
        let missing = dead_limit - post;
        let severity = 1.0 + (1.0 - post / dead_limit).powi(2);
        let dead_weight = (2.4 + 1.3 * open_pressure + 0.6 * progress + 0.5 * mean_norm) * severity;
        score += missing * dead_weight;
    }

    // Breaking the immediate lookahead chain is a serious fragmentation cost.
    if next > 0.0 && post > 0.0 && post < next {
        score += cap * (0.45 + 0.35 * (1.0 - post / next));
    }

    // Reward placements that leave just enough room for the next item,
    // with a tighter quadratic curve favoring snug fits.
    if next > 0.0 && post >= next {
        let slack = ((post - next) / cap).clamp(0.0, 1.0);
        let tightness = 1.0 - slack * slack;
        score -= cap * (0.18 + 0.07 * progress) * tightness;

        // Exact-multiple chain potential: post_residual a clean multiple of
        // next_item_size enables a sequence of future perfect fits.
        let ratio = post / next;
        let mult_err = (ratio - ratio.round()).abs();
        if mult_err < 0.02 {
            score -= cap * 0.06 * (1.0 - 0.5 * progress);
        }
    }

    // Two-step lookahead: stranded tiny gaps late in the stream.
    if post > 0.0 && next > 0.0 && post < next && post < 0.06 * cap {
        score += cap * (0.15 + 0.20 * progress);
    }

    // Fragmentation-anticipation: residuals in the awkward band just above
    // the next item but below next + mean item likely become dead space.
    if !is_new_bin && post > next && next > 0.0 {
        let awkward = (next + mean_residual.min(cap)).min(cap);
        if post < awkward {
            let depth = 1.0 - (awkward - post) / awkward.max(1.0);
            score += cap * 0.08 * depth * (0.5 + 0.5 * progress);
        }
    }

    if is_new_bin {
        let fit_pressure = fitting.min(4.0);
        let mut new_penalty = cap
            * (0.18 + 0.45 * open_pressure + 0.10 * mean_norm + 0.05 * fit_pressure)
            * (1.10 - 0.25 * item_norm);

        // A new bin that cannot absorb the next item is especially wasteful.
        if next > 0.0 && post < next {
            new_penalty += cap * (0.70 + 0.25 * (1.0 - post / next));
        }

        // Late in the stream, opening bins is nearly always wasteful.
        new_penalty += cap * 0.10 * progress;

        // Relax penalty when current bins are already highly fragmented.
        new_penalty *= 1.0 - 0.15 * (1.0 - mean_norm) * open_pressure;

        // Opening is attractive when the item nearly fills a fresh bin.
        if item_norm > 0.90 {
            new_penalty -= cap * 0.35 * (item_norm - 0.90) / 0.10;
        }

        // When no next item is known, opening is mildly cheaper.
        if next == 0.0 {
            new_penalty -= cap * 0.05 * (1.0 - progress);
        }

        score += new_penalty;
    } else if fitting_bins_count == 1 {
        // Strongly prefer the last open bin that can still take the item.
        score -= cap * (0.20 + 0.30 * open_pressure + 0.05 * progress);
    } else if next > 0.0 {
        // Chain-fit preference: reward residuals close to a multiple of the
        // next item size, scaled by how many competing bins exist.
        let ratio = post / next;
        let chain_fit = (ratio.round() - ratio).abs();
        let chain_weight = 0.06 + 0.02 * fitting.min(5.0);
        score += chain_fit * next * chain_weight;
    }

    // Prefer bins whose residual stays usable for the average remaining item.
    if !is_new_bin && post > 0.0 && mean_residual > 0.0 {
        let usable = (post / mean_residual).clamp(0.0, 4.0);
        score += (2.0 - usable).abs() * 0.05 * cap * (1.0 - progress);
    }

    // Compaction reward: prefer the fullest bins after placement, strongest
    // when few alternative bins compete.
    if !is_new_bin && post > 0.0 {
        let fill_after = 1.0 - post / cap;
        score -= fill_after * cap * 0.05 * (1.0 - fitting.min(3.0) / 3.0);
    }

    // NEW: explicit frag-zone penalty for residual slivers relative to capacity,
    // combined with lookahead anticipation of chain breakage.
    let frag = (post / cap).clamp(0.0, 1.0);
    let frag_zone = 0.10 * (1.0 - progress) + 0.04;
    if !is_new_bin && frag > 0.0 && frag < frag_zone {
        let frag_sev = 1.0 - frag / frag_zone;
        score += cap * frag_sev * (0.08 + 0.12 * open_pressure + 0.06 * mean_norm);
        if next > 0.0 && next > post {
            score += cap * 0.10 * frag_sev;
        }
    }

    // NEW: multi-fit chain reward — residual that cleanly fits next item two
    // or more times enables a run of perfect placements.
    if !is_new_bin && fitting_bins_count >= 2 && next > 0.0 && post >= next {
        let alt_ratio = post / next;
        if alt_ratio.fract() < 0.15 && alt_ratio >= 2.0 {
            score -= cap * 0.04 * (1.0 - progress);
        }
    }

    // NEW: snug double-fit bonus — residual holding exactly one next item,
    // tightened toward 2*next, compacts the bin faster.
    if !is_new_bin && post > next && next > 0.0 && post >= next && post < 2.0 * next {
        score -= cap * 0.03 * (1.0 - 0.5 * progress) * (1.0 - (post / next - 1.0));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: capacity fractions /10
    let item_class = item_size / 10;
    let post_class = post_residual / 10;

    // Reward post_residuals that fall into "usable" harmonic classes (multiples of 10)
    // i.e., dead space that another item of a common class could still fill.
    if post_residual > 0 {
        let waste = (post_residual % 10) as f64;
        score += waste * 1.5; // penalize ragged remainders
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward leaving room exactly matching common item classes
    let usable = if post_residual >= 10 { 10.0 } else { 0.0 };
    score -= usable;

    // Harmonic pairing: does post_residual accommodate next_item_size?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // exact next-item fit is golden
            if post_residual == next_item_size {
                score -= 60.0;
            } else {
                let next_class = next_item_size / 10;
                // reward if post_residual's class is >= next class (coarse compatibility)
                if post_class >= next_class {
                    score -= 8.0 + (post_class - next_class) as f64 * 2.0;
                }
                // penalize overshoot creating tiny dead zone
                let slack = post_residual - next_item_size;
                if slack > 0 && slack < 10 {
                    score += 10.0;
                }
            }
        } else {
            // placing here strands the next item's class relationship
            score += 15.0;
        }
    } else {
        // last item: prefer tightest fit strongly
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin gets a moderate default,
    // beaten only when an open bin fits well.
    if bin_residual == bin_capacity {
        score = 70.0;
        // early in stream, opening bins is cheap
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 30.0 * (1.0 - progress);
        // big items justify fresh bins
        if item_class >= 7 {
            score -= 15.0;
        }
    }

    // Coupling with mean residual: if this bin is much emptier than average,
    // prefer filling it (balance preservation).
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.3;

    // Many open bins: discourage opening new ones
    if open_bins_count > 4 && bin_residual == bin_capacity {
        score += 5.0 * open_bins_count as f64;
    }

    // Modulo-based dead-space penalty on bin_residual class
    if bin_residual % 10 != 0 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: any residual that is too small to hold the
    // minimum item size (1) is perfect, but small "unusable" gaps relative to
    // typical item sizes are heavily penalized.
    let dead_threshold: u32 = 10; // smallest classic item size
    if post_residual > 0 && post_residual < dead_threshold {
        score += 500.0; // near-waste gap
    } else if post_residual >= dead_threshold && post_residual < item_size.min(dead_threshold * 2) {
        score += 120.0; // awkward gap unlikely to be filled
    } else if post_residual == 0 {
        score -= 200.0; // perfect fill
    }

    // Non-linear penalty on wasted fraction of the bin.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 60.0 * waste_frac * waste_frac;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // Open-bin pressure: when many bins are open, discourage new bins and
    // encourage consolidation into existing ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (0.5 + progress);

    // New-bin candidate (empty bin): make it costly unless the fit is bad
    // everywhere else or the item is large.
    if bin_residual == bin_capacity {
        score += 250.0 + 2.0 * open_bins_count as f64;
        if item_size > bin_capacity * 3 / 4 {
            score -= 150.0; // large items may warrant fresh bins
        }
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // reward this placement strongly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 180.0;
        } else if post_residual > next_item_size {
            score -= 20.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 40.0; // blocks the lookahead item
        }
    }

    // Prefer bins tighter than the current mean residual (good packing).
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, but only if the leftover is still usable.
    if post_residual == 0 {
        score -= 200.0; // perfect fill
    } else if post_residual < 10 {
        score += 60.0; // dead space: too small for the smallest item
    }

    // 2-step lookahead: reward when next item fits exactly into post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 150.0; // perfect chain fill
        } else if post_residual >= next_item_size {
            let next_leftover = post_residual - next_item_size;
            if next_leftover == 0 {
                score -= 180.0;
            } else if next_leftover < 10 {
                score += 40.0; // chain would create dead space
            } else {
                // reward proportional closeness of next item to post_residual
                let fit_ratio = next_item_size as f64 / post_residual as f64;
                score -= 90.0 * fit_ratio;
            }
        } else {
            // next item won't fit here; slight penalty if we'd strand space
            score += 15.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Relative to mean residual: prefer bins that are tighter than average.
    score -= 0.5 * (mean_residual - bin_residual as f64).max(0.0);

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 100.0;
    }

    // New-bin candidate handling: make empty bins attractive only when
    // no open bin offers a genuinely good fit.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Empty bin baseline: moderate score, beaten by good fits.
        score = 55.0 + 20.0 * progress;
        if next_item_size > 0 && next_item_size >= item_size {
            // reserving a fresh bin for a big next item is reasonable
            score -= 25.0;
        }
        if open_bins_count == 0 {
            score = -500.0; // must open first bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near 0 is best.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space: residuals too small for the smallest plausible item.
    let min_item = 1.0f64;
    if (post_residual as f64) < min_item * 3.0 {
        score += 6.0;
    } else if post_residual > 0 && post_residual < 10 {
        score += 4.0; // small unusable sliver
    }

    // Lookahead: if next item fits in post_residual, big bonus (chain placement).
    if next_item_size > 0 {
        if (next_item_size as u32) <= post_residual {
            let slack = post_residual as f64 - next_item_size as f64;
            score -= 14.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 3.0; // next item won't chain here
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Prefer bins with below-mean residual (keep big holes open for big items).
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 10.0 * dev;

    // Time horizon: early in stream, be conservative about opening new bins;
    // late in stream, tighter packing matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when existing bins fit poorly
    // (large post_residual relative to next item) or many bins already open.
    if bin_residual == bin_capacity {
        let open_cost = 12.0 + 0.4 * open_bins_count as f64;
        let escape_benefit = if next_item_size > 0 && item_size as f64 + next_item_size as f64 > bin_capacity as f64 {
            8.0 // reserving fresh bin for a big pair
        } else {
            0.0
        };
        let poor_fit_elsewhere = if fitting_bins_count > 0 {
            (post_residual as f64 / bin_capacity as f64) * 4.0
        } else {
            0.0
        };
        score += open_cost - escape_benefit - poor_fit_elsewhere;
    }

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    let cap = bin_capacity.max(1) as f64;
    let post = post_residual as f64;
    let next = next_item_size as f64;
    let open = open_bins_count as f64;
    let fitting = fitting_bins_count as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let mean_norm = (mean_residual / cap).clamp(0.0, 1.0);
    let item_norm = (item_size as f64 / cap).clamp(0.0, 1.0);
    let open_pressure = open / (open + 5.0);
    let is_new_bin = bin_residual == bin_capacity;

    let mut score = post * 0.95 + item_norm * 0.05;

    // Reward exact closure, scaled by crowding.
    if post_residual == 0 {
        score -= cap * (0.24 + 0.30 * open_pressure + 0.10 * progress);
    }

    // Dead-space avoidance: linear severity with convex boost for thin slivers.
    let dead_limit = next.max(0.10 * cap);
    if post > 0.0 && post < dead_limit {
        let missing = dead_limit - post;
        let mut dead_weight = 2.4 + 1.3 * open_pressure + 0.6 * progress + 0.5 * mean_norm;
        let thinness = 1.0 - post / dead_limit;
        if thinness > 0.7 {
            dead_weight += (thinness - 0.7) * 3.0;
        }
        score += missing * dead_weight;
    }

    // Breaking the immediate lookahead chain is a serious fragmentation cost.
    if next > 0.0 && post > 0.0 && post < next {
        score += cap * (0.45 + 0.35 * (1.0 - post / next));
    }

    // Reward placements that leave just enough room for the next item.
    if next > 0.0 && post >= next {
        let slack = ((post - next) / cap).clamp(0.0, 1.0);
        let tightness = 1.0 - slack * slack;
        score -= cap * (0.18 + 0.07 * progress) * tightness;

        let ratio = post / next;
        let mult_err = (ratio - ratio.round()).abs();
        if mult_err < 0.02 {
            score -= cap * 0.06 * (1.0 - 0.5 * progress);
        }
    }

    // Two-step lookahead: stranded tiny gaps late in the stream.
    if post > 0.0 && next > 0.0 && post < next && post < 0.06 * cap {
        score += cap * (0.15 + 0.20 * progress);
    }

    // Fragmentation-anticipation in the awkward band above next item.
    if !is_new_bin && post > next && next > 0.0 {
        let awkward = (next + mean_residual.min(cap)).min(cap);
        if post < awkward {
            let depth = 1.0 - (awkward - post) / awkward.max(1.0);
            score += cap * 0.08 * depth * (0.5 + 0.5 * progress);
        }
    }

    if is_new_bin {
        let fit_pressure = fitting.min(4.0);
        let mut new_penalty = cap
            * (0.18 + 0.45 * open_pressure + 0.10 * mean_norm + 0.05 * fit_pressure)
            * (1.10 - 0.25 * item_norm);

        if next > 0.0 && post < next {
            new_penalty += cap * (0.70 + 0.25 * (1.0 - post / next));
        }

        new_penalty += cap * 0.10 * progress;

        new_penalty *= 1.0 - 0.15 * (1.0 - mean_norm) * open_pressure;

        if item_norm > 0.90 {
            new_penalty -= cap * 0.35 * (item_norm - 0.90) / 0.10;
        }
        if next == 0.0 {
            new_penalty -= cap * 0.05 * (1.0 - progress);
        }

        score += new_penalty;
    } else if fitting_bins_count == 1 {
        score -= cap * (0.20 + 0.30 * open_pressure + 0.05 * progress);
    } else if next > 0.0 {
        let ratio = post / next;
        let chain_fit = (ratio.round() - ratio).abs();
        let chain_weight = 0.06 + 0.02 * fitting.min(5.0);
        score += chain_fit * next * chain_weight;
    }

    // Prefer bins whose residual stays usable for the average remaining item.
    if !is_new_bin && post > 0.0 && mean_residual > 0.0 {
        let usable = (post / mean_residual).clamp(0.0, 4.0);
        score += (2.0 - usable).abs() * 0.05 * cap * (1.0 - progress);
    }

    // Compaction reward: prefer the fullest bins after placement.
    if !is_new_bin && post > 0.0 {
        let fill_after = 1.0 - post / cap;
        score -= fill_after * cap * 0.05 * (1.0 - fitting.min(3.0) / 3.0);
    }

    // Residual-parity coupling: post-residual pairs with mean residual for a future exact fit.
    if !is_new_bin && post > 0.0 && mean_residual > 1.0 {
        let pair = post + mean_residual;
        let pair_err = (pair / cap - (pair / cap).round()).abs();
        if pair_err < 0.03 && pair <= cap {
            score -= cap * 0.05 * (1.0 - progress);
        }
    }

    // Lookahead anticipation: post-residual matches next item with a small usable gap.
    if !is_new_bin && fitting > 1.0 && next > 0.0 && post >= next {
        let gap = post - next;
        if gap > 0.0 && gap < 0.15 * cap {
            score -= cap * 0.10 * (1.0 - gap / (0.15 * cap));
        }
        let alt_ratio = post / next;
        if alt_ratio >= 2.0 && alt_ratio.fract() < 0.15 {
            score -= cap * 0.04 * (1.0 - progress);
        }
    }

    // Borrowed: explicit early-phase frag-zone penalty on tiny residuals.
    let frag = if post > 0.0 { (post / cap).clamp(0.0, 1.0) } else { 0.0 };
    let frag_zone = 0.10 * (1.0 - progress) + 0.04;
    if !is_new_bin && frag > 0.0 && frag < frag_zone {
        let frag_sev = 1.0 - frag / frag_zone;
        score += cap * frag_sev * (0.08 + 0.12 * open_pressure + 0.06 * mean_norm);
        if next > 0.0 && next > post {
            score += cap * 0.10 * frag_sev;
        }
    }

    // Near-double-fit bonus: residual that could hold next item twice.
    if !is_new_bin && post > next && next > 0.0 && post < 2.0 * next {
        score -= cap * 0.03 * (1.0 - 0.5 * progress) * (1.0 - (post / next - 1.0));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post;

    // Smooth polynomial coupling of post_residual with stream progress.
    let pr_norm = post / cap;
    let poly = progress * progress * (1.0 - progress) * 4.0; // smooth bump, zero at ends
    score += 12.0 * pr_norm * pr_norm * (1.0 + poly);

    // Penalize dead space more as stream progresses (less time to fill it).
    score += 6.0 * pr_norm * progress;

    // Reward tight fits: subtract when post_residual is small.
    score -= 8.0 * (1.0 - pr_norm) * (1.0 - pr_norm);

    // Last-chance bonus: avoid opening a new bin when this is the only fitting one.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: prefer leaving room for the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 5.0 * (post - nxt) / cap;
        } else {
            score += 4.0 * (nxt - post) / cap;
        }
    }

    // Mild penalty when many bins are open and residual is far above mean.
    let mean = mean_residual;
    score += 0.05 * (post - mean).abs() * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));

    // New-bin candidate: keep it slightly unattractive unless residuals are tight.
    if bin_residual == bin_capacity {
        score += 3.0 + 10.0 * (1.0 - progress) * (1.0 - progress);
    }

    score
}

