pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: residues near capacity fractions
    let cap_f = bin_capacity as f64;
    let pr = post_residual as f64;

    // Penalize dead space that is too small to be useful later.
    // Classes: (0,10] = near-dead, (10,25] = small-item only, (25,50] = mid, >50 = valuable
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0; // dead space penalty
    } else if post_residual <= 25 {
        score += 25.0;
    } else if post_residual <= 50 {
        score -= 5.0;
    } else {
        score -= 15.0;
    }

    // Modulo arithmetic: residuals that are multiples of common item sizes (10, 20, 25)
    // are reusable by future items, reward them.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 12.0;
    }
    if post_residual % 25 == 0 {
        score -= 6.0;
    }

    // Lookahead coupling: does the next item fit in the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 20.0; // chainable placement
            // extra reward if next item exactly fills the leftover
            if next_item_size == post_residual {
                score -= 30.0;
            }
        } else {
            // leftover too small for next item: penalize proportionally to wasted fraction
            let waste = 1.0 - pr / (next_item_size as f64);
            score += 15.0 * waste;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate handling: empty bin should only win when no open bin fits well
    if bin_residual == bin_capacity {
        score += 90.0; // base cost of opening a new bin
        // Cheaper to open a new bin late in the stream? No: late stream favors closing out bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * progress;
        // If open bins are fragmented (high mean residual spread), new bin more attractive
        if mean_residual < 30.0 {
            score -= 10.0;
        }
        // If next item is large, a fresh bin is valuable
        if next_item_size > bin_capacity / 2 {
            score -= 15.0;
        }
    }

    // Mild preference to spread load across many open bins when few are open
    if open_bins_count < 4 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong dead-space penalty: residuals too small to ever fit another item
