        let nxt = next_item_size as f64;
        if (pr + 0.5) < nxt {
            score += 0.4 * (nxt - pr) / cap * (0.5 + progress);
        } else {
            score -= 0.2 * (1.0 - (pr - nxt).abs() / cap) * (1.0 - progress);
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
