pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "usable" residue classes (multiples of small divisors) are favored.
    let r = post_residual;
    if r == 0 {
        score -= 60.0; // perfect fill, ideal
    } else if r % 10 == 0 {
        score -= 12.0; // decile-aligned leftover stays reusable
    } else if r % 5 == 0 {
        score -= 6.0;
    } else if r <= 10 {
        score += 25.0; // tiny dead space, penalize
    } else {
        // fractional dead-space penalty scaled by how far from a harmonic class
        let dev = (r % 10).min(10 - r % 10) as f64;
        score += dev * 0.8;
    }

    // Integer-division threshold: leftover that can hold the next item is good
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0 + 0.25 * (post_residual - next_item_size) as f64;
        } else {
            score += 8.0 + (next_item_size - post_residual) as f64 * 0.3;
        }
        // next item itself in a harmonic class -> plan capacity fractions
        if next_item_size % 10 == 0 {
            score -= 4.0;
        }
    } else {
        // last item: just fill as tightly as possible
        score -= 20.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New empty bin candidate: only attractive when current fit is terrible
    // or stream is early and we want many bins to choose from.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = (post_residual as f64) > 40.0;
        if poor_fit || open_bins_count == 0 {
            score -= 18.0 + 20.0 * (1.0 - progress);
