        score += 4.0;
    }

    // Mild pressure to consolidate when many bins are open
    score += (open_bins_count as f64).ln().max(0.0) * (post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead space penalty: residuals that are too small to fit typical items are wasted.
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += 40.0 - 3.0 * post_residual as f64;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    } else {
        // Reward tight fits relative to bin capacity.
        let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
        score -= 10.0 * tightness;
    }

    // Lookahead: penalize if the next item can't use the post residual.
    if next_item_size > 0 {
        if (next_item_size as f64) > post_residual as f64 && post_residual > 0 {
            score += 0.5 * (next_item_size as f64 - post_residual as f64);
        } else if next_item_size as u32 <= post_residual {
            score -= 3.0;
        }
    }

    // Last-chance bonus: avoid opening a new bin if this is the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Pressure from number of open bins: discourage proliferation of bins.
    score += 0.35 * open_bins_count as f64;

    // New-bin candidate: only attractive when current bins are badly fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).max(0.0);
        if fragmentation > 45.0 {
            score -= 6.0;
        } else {
            score += 18.0;
        }
    }

    // Mild stream progression term: later in the stream, be slightly more conservative.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 2.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: prefer bins deviating favorably from the mean.
    score -= 0.05 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
