    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let bonus = if fitting_bins_count == 0 { 0.0 } else { 25.0 + 10.0 * (1.0 - progress) };
        score += bonus;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * 20.0;

    // Penalize dead space that next item cannot use.
    if next_item_size > 0 && post_residual > 0 {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.6;
        } else {
            // residual can host the next item: reward
            score -= 3.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Empty-bin (new bin) candidate: penalize mildly so we only open a new bin
    // when no open bin fits well; but reward it when current bins are nearly full.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_pressure = mean_residual / bin_capacity as f64;
        // new bin gets a base penalty, reduced when open bins are congested
        score += 35.0 - 30.0 * (1.0 - avg_pressure).min(1.0);
        // early in stream, opening new bins is cheap; late, prefer filling
        score += 10.0 * (1.0 - progress);
        // if next item is large and current residual small, new bin is attractive
        if next_item_size > item_size && bin_residual - item_size < next_item_size {
            score -= 8.0;
        }
    }

    // Prefer bins whose residual is close to item size (best-fit shaping),
    // with a non-linear coupling on mean residual.
    let fit_gap = (bin_residual as f64 - item_size as f64).abs();
    score += fit_gap * 0.15 * (1.0 + mean_residual / (bin_capacity as f64 * 4.0));

    // Penalize very small leftover slivers that nothing (min size 1) could use well.
    if post_residual > 0 && post_residual < 10 {
        score += 5.0;
    }

    // Mild reward for consolidating into bins with many siblings (keeps bin count low)
    if open_bins_count > 0 && bin_residual < bin_capacity {
        score -= (open_bins_count as f64).ln().max(0.0) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with smooth polynomial shaping.
    // Small post-residuals (tight fits) are rewarded quadratically; large ones penalized.
    let mut score = norm_pr * (1.0 + 2.0 * norm_pr * norm_pr);

    // Coupling with stream progress: early on, prefer filling bins loosely to build
    // flexibility; later, demand tight fits (amplify small post_residual reward).
    let tightness = (1.0 - norm_pr).powi(3);
    score -= 3.0 * progress * tightness;
    score += 1.5 * (1.0 - progress) * norm_pr * norm_pr;

    // Lookahead: if next item fits into the post residual, reward strongly (smooth bump).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let fit_quality = nx / pr;
            score -= 2.5 * fit_quality * (1.0 - fit_quality) * 4.0 * (0.25 + progress);
        } else {
            // Dead space risk if next item can't use the leftover.
            let gap = (nx - pr) / cap;
            score += 2.0 * gap * (0.5 + progress);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 4.0 + 2.0 * tightness;
    } else if fitting_bins_count > 1 {
        // Mild penalty so among many fitting bins, the tightest wins via base term.
        score += 0.3 * (fitting_bins_count.min(10) as f64 - 1.0);
    }

    // New-bin candidate handling: only attractive when open bins are fragmented
    // (mean residual small relative to item) or late in stream with many bins.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap) * (open_bins_count as f64).sqrt();
        score = 6.0 - 4.0 * fragmentation - 3.0 * progress * (1.0 - fragmentation.min(1.0));
        if next_item_size > 0 && (next_item_size as f64) <= cap {
            // A fresh bin guarantees room for the next item too.
            score -= 1.0;
        }
    }

    // Mean residual coupling: bins far from the mean residual are slightly demoted
    // (prefer consistent residual structure), with smooth quadratic term.
    let dev = (pr - mean_residual) / cap;
    score += 0.5 * dev * dev;

    score
}
